export const schema = {"$schema":"http://json-schema.org/draft-07/schema#","version":"1.21.0","generatedAt":"2026-06-17","package":"@usevyre/react","packageVersion":"1.21.0","validFor":["@usevyre/react@1.1.0+","@usevyre/vue@1.1.0+"],"changelog":{"1.21.0":{"date":"2026-06-17","breaking":false,"summary":"Added 5 chart components: Sparkline (tiny inline chart, data=number[], variant line/area/bar), and the data+config driven LineChart, AreaChart, BarChart and PieChart. Charts are data + config + xKey driven (NOT Recharts-style JSX children); colors come from config tokens, not a color prop. PieChart takes flat {name,value}[] data. Includes anti-patterns steering agents away from series={...}, color=\"blue\", <XAxis/>/<Tooltip/>/<Pie>/<Cell> children, and numeric pie data."},"1.20.0":{"date":"2026-06-15","breaking":false,"summary":"RichTextEditor security: new optional `sanitize` (html)=>html prop applied on render-in and emit-out (component stays zero-dependency; pass DOMPurify yourself for untrusted HTML). The link tool now always blocks javascript:/data:/vbscript: URLs. Corrected the misleading 'sanitised-friendly' doc note."},"1.19.0":{"date":"2026-06-15","breaking":false,"summary":"Tooltip: now portals to <body> by default so it stays visible inside Modal / overflow:hidden containers (same overlay-clip fix as Combobox #18 / Select). New `disablePortal` boolean (default false) restores inline rendering."},"1.18.0":{"date":"2026-06-15","breaking":false,"summary":"Select: dropdown now portals to <body> by default so it stays visible inside Modal / overflow:hidden containers (same fix as Combobox #18). New `disablePortal` boolean (default false) restores inline rendering."},"1.17.0":{"date":"2026-06-14","breaking":false,"summary":"Combobox: dropdown now portals to <body> by default so it stays visible inside Modal / overflow:hidden containers (issue #18). New `disablePortal` boolean (default false) restores inline rendering."},"1.16.2":{"date":"2026-05-20","breaking":false,"summary":"Fix schema↔code drift in 5 props: Modal/Sheet `title` (use ModalHeader/SheetHeader sub-component instead), Pagination `total`→`totalPages`, Tabs `defaultIndex/index` (number)→`defaultValue/value` (string keys). Schema now matches the shipped React/Vue prop names and types."},"1.16.1":{"date":"2026-05-19","breaking":false,"summary":"Fix schema↔code drift: Switch/Checkbox onChange→onCheckedChange, Slider onChange→onValueChange, Pagination onChange→onPageChange (+ example total→totalPages). Schema now matches the shipped React/Vue prop names."},"1.16.0":{"date":"2026-05-18","breaking":false,"summary":"Added Carousel + CarouselSlide: accessible controlled content slider with snap scrolling, dot indicators, prev/next arrows, keyboard navigation, optional loop and autoPlay (pauses on hover/focus). Completes the post-1.3 backlog (10/10 components)."},"1.15.0":{"date":"2026-05-18","breaking":false,"summary":"Added OTPInput: segmented one-time-code input for 2FA/verification with controlled string value, paste-aware fill, auto-advance/backspace, arrow keys, onComplete, type (numeric/alphanumeric), mask and sizes."},"1.14.0":{"date":"2026-05-18","breaking":false,"summary":"Added Tree: data-driven, controlled hierarchical tree view (file explorer / nested nav) with recursive rendering, controlled expanded/selected state, and full keyboard navigation."},"1.13.0":{"date":"2026-05-18","breaking":false,"summary":"Added Timeline + TimelineItem: vertical activity feed for audit logs/history with status-colored markers, connector line, and items[] or composable children for rich content."},"1.12.1":{"date":"2026-05-18","breaking":false,"summary":"Fix Stat: the arrow direction now follows the sign of `delta` (the actual change) instead of `trend`. `trend` controls only the color. So a falling 'lower is better' metric correctly shows a green DOWN arrow."},"1.12.0":{"date":"2026-05-18","breaking":false,"summary":"Added Stat + StatGroup: presentational dashboard KPI with an explicit trend (up/down/neutral) that controls the delta color, sizes, optional icon, and an evenly-split StatGroup row."},"1.11.0":{"date":"2026-05-18","breaking":false,"summary":"Added EmptyState: presentational placeholder for empty lists/tables/search with preset variant icons (default/search/error), sizes, and a composed call-to-action."},"1.10.0":{"date":"2026-05-18","breaking":false,"summary":"Added Stepper + StepperNav + Step + StepPanel: controlled multi-step flow (0-based index) for wizards/onboarding/checkout, horizontal or vertical, with automatic completed/current/upcoming states and optional clickable back-navigation."},"1.9.0":{"date":"2026-05-18","breaking":false,"summary":"Added ToggleGroup + ToggleItem: controlled segmented control with single/multiple modes (value adapts: string|null vs string[]), options[] or composable children, keyboard navigation. Emits the value, not an event."},"1.8.0":{"date":"2026-05-18","breaking":false,"summary":"Added NumberInput: controlled numeric input with −/+ stepper, min/max/step/precision, clamp-on-blur and keyboard stepping. Emits number|null (not an event) and composes directly with Form/FormField."},"1.7.0":{"date":"2026-05-18","breaking":false,"summary":"Added Form + FormField: controlled, data-driven, zero-dependency form with built-in validation rules (required/minLength/maxLength/min/max/pattern/email/custom) that map errors into Field automatically."},"1.6.0":{"date":"2026-05-18","breaking":false,"summary":"Documented the spacing model as an explicit anti-pattern on representative components (Button, Card, Input): useVyre components take no padding/margin props — use Stack/Grid gap or a Box wrapper. No API change."},"1.5.0":{"date":"2026-05-18","breaking":false,"summary":"Stack, Grid and Box gain token-locked width / height props (keywords auto/full/fit/screen + fixed-rem token sizes xs–2xl), removing the need for an inline width/height style for common layout sizing."},"1.4.0":{"date":"2026-05-18","breaking":false,"summary":"Layout primitives expanded: Stack now covers the full CSS flexbox surface (reverse directions, wrap modes, alignContent/alignSelf, grow/shrink/basis, per-axis gap); Grid gains rows/flow/justify + a new GridItem subcomponent for span/placement; Box gains per-axis (X/Y) and per-side (Top/Right/Bottom/Left) token padding/margin. Fixes Grid columns being overwritten when a user style prop was passed."},"1.3.0":{"date":"2026-05-18","breaking":false,"summary":"Added Stack, Grid and Box layout primitives. Token-locked spacing (no raw px/rem) to eliminate hallucinated inline flex/grid styles; Box exposes a documented style escape hatch flagged as an anti-pattern."},"1.2.0":{"date":"2026-05-16","breaking":false,"summary":"Added Item layout primitive, DateRangePicker (dual-month range picker with presets, built on Calendar) and Kanban (controlled drag-and-drop board); Calendar gained additive defaultMonth prop; DatePicker split into its own documented component/entry"},"1.1.0":{"date":"2026-05-15","breaking":false,"summary":"Added 6 components: ButtonGroup, TagsInput, Combobox, DataGrid, Tag, TagGroup"},"1.0.0":{"date":"2026-05-13","breaking":true,"summary":"Stable v1.0 release — VyreCode renamed to Code in Vue, BreadcrumbLink + BreadcrumbSeparator added to React, Toast setup updated"},"0.2.0":{"date":"2026-05-08","breaking":false,"summary":"Added structured schema, anti-patterns JSON, per-tool format generation"},"0.1.1":{"date":"2026-05-06","breaking":false,"summary":"Initial AI context with full-context.md, cursor/claude/windsurf/copilot formats"}},"components":{"Accordion":{"description":"Vertically stacked collapsible sections. Compose with AccordionItem, AccordionTrigger, AccordionContent.","import":"import { Accordion, AccordionItem, AccordionTrigger, AccordionContent } from \"@usevyre/react\"","subcomponents":["AccordionItem","AccordionTrigger","AccordionContent"],"props":{},"antiPatterns":[{"pattern":"Accordion without AccordionItem","reason":"Accordion requires AccordionItem as direct child","fix":"Always compose: Accordion > AccordionItem > AccordionTrigger + AccordionContent"}],"examples":[{"description":"Basic accordion","code":"<Accordion>\n  <AccordionItem value=\"item-1\">\n    <AccordionTrigger>Section Title</AccordionTrigger>\n    <AccordionContent>Content goes here.</AccordionContent>\n  </AccordionItem>\n</Accordion>"}]},"Alert":{"description":"Inline feedback message for info, success, warning, or danger states.","import":"import { Alert } from \"@usevyre/react\"","props":{"variant":{"type":"enum","values":["info","success","warning","danger"],"default":"info","description":"Visual severity style"},"title":{"type":"string","description":"Bold heading text inside the alert"},"onClose":{"type":"function","description":"If provided, renders a close (×) button"}},"antiPatterns":[{"pattern":"variant=\"error\"","reason":"No 'error' variant exists","fix":"Use variant=\"danger\""},{"pattern":"variant=\"primary\"","reason":"Alert uses severity variants, not brand variants","fix":"Use variant=\"info\" | \"success\" | \"warning\" | \"danger\""}],"examples":[{"description":"Warning with close button","code":"<Alert variant=\"warning\" title=\"Heads up\" onClose={() => setOpen(false)}>\n  This action cannot be undone.\n</Alert>"},{"description":"Success state","code":"<Alert variant=\"success\" title=\"Saved!\">Your changes have been saved.</Alert>"}]},"AlertDialog":{"description":"Blocking confirmation modal (focus-trapped). Controlled via open + onOpenChange (React) / v-model (Vue). Use for destructive or irreversible actions that need explicit confirm/cancel. For non-blocking inline feedback use Alert; for general dialogs use Modal.","import":"import { AlertDialog } from \"@usevyre/react\"","props":{"open":{"type":"boolean","description":"Controlled visibility. Vue: v-model."},"onOpenChange":{"type":"function","description":"(open: boolean) => void — called when the dialog requests to close (backdrop, Esc, cancel). Vue: update:modelValue / v-model."},"title":{"type":"string","description":"Dialog heading (required)."},"description":{"type":"string","description":"Supporting body text."},"variant":{"type":"enum","values":["danger","warning","info"],"default":"info","description":"Visual tone of the confirm action / icon."},"confirmLabel":{"type":"string","default":"Confirm","description":"Confirm button text."},"cancelLabel":{"type":"string","default":"Cancel","description":"Cancel button text."},"onConfirm":{"type":"function","description":"Called when the confirm button is pressed."},"onCancel":{"type":"function","description":"Called when cancelled (button, Esc, backdrop)."}},"antiPatterns":[{"pattern":"AlertDialog without open/onOpenChange (React) or v-model (Vue)","reason":"It is controlled; it never shows/closes without state","fix":"Drive open from state; close in onOpenChange / via v-model"},{"pattern":"Using Alert (inline banner) for a confirm/cancel decision","reason":"Alert is non-blocking inline feedback, has no confirm flow","fix":"Use AlertDialog for blocking confirmation; Alert for passive messages"},{"pattern":"variant=\"success\" or \"error\"","reason":"AlertDialog variant is \"danger\" | \"warning\" | \"info\" only","fix":"Use \"danger\" for destructive, \"warning\" to caution, \"info\" otherwise"}],"examples":[{"description":"Destructive confirmation","code":"const [open, setOpen] = useState(false);\n<Button variant=\"danger\" onClick={() => setOpen(true)}>Delete</Button>\n<AlertDialog\n  open={open}\n  onOpenChange={setOpen}\n  variant=\"danger\"\n  title=\"Delete project?\"\n  description=\"This cannot be undone.\"\n  confirmLabel=\"Delete\"\n  onConfirm={() => deleteProject()}\n/>"}]},"Avatar":{"description":"User profile image with fallback initials or icon.","import":"import { Avatar } from \"@usevyre/react\"","props":{"src":{"type":"string","description":"Image URL. Falls back to `fallback` if not provided or fails to load."},"alt":{"type":"string","default":"\"\"","description":"Alt text for the image"},"fallback":{"type":"string","description":"Text or initials shown when image is absent"},"size":{"type":"enum","values":["sm","md","lg","xl"],"default":"md","description":"Avatar diameter"},"status":{"type":"enum","values":["online","offline","busy","away"],"description":"Optional status indicator dot"}},"antiPatterns":[{"pattern":"size=\"xs\"","reason":"Minimum size is 'sm'","fix":"Use size=\"sm\""},{"pattern":"size=\"2xl\"","reason":"Maximum size is 'xl'","fix":"Use size=\"xl\""}],"examples":[{"description":"Avatar with image and online status","code":"<Avatar src=\"/user.png\" alt=\"Jane Doe\" size=\"lg\" status=\"online\" />"},{"description":"Fallback initials","code":"<Avatar fallback=\"JD\" size=\"md\" />"}]},"Badge":{"description":"Small label for status, category, or count. Use dot prop for live status indicator.","import":"import { Badge } from \"@usevyre/react\"","props":{"variant":{"type":"enum","values":["default","accent","teal","success","warning","danger"],"default":"default","description":"Color style of the badge"},"dot":{"type":"boolean","default":false,"description":"Shows a pulsing status indicator dot"}},"antiPatterns":[{"pattern":"variant=\"primary\"","reason":"Badge has no 'primary' variant","fix":"Use variant=\"accent\" for brand color"},{"pattern":"variant=\"error\"","reason":"No 'error' variant exists","fix":"Use variant=\"danger\""},{"pattern":"variant=\"info\"","reason":"No 'info' variant on Badge (use Alert for info messages)","fix":"Use variant=\"teal\" for info-like styling"}],"examples":[{"description":"Live status with dot","code":"<Badge variant=\"success\" dot>Online</Badge>"},{"description":"Warning badge","code":"<Badge variant=\"warning\">Beta</Badge>"},{"description":"Danger badge","code":"<Badge variant=\"danger\">Error</Badge>"}]},"Breadcrumb":{"description":"Navigation trail showing current page location in hierarchy.","import":"import { Breadcrumb, BreadcrumbItem, BreadcrumbLink, BreadcrumbSeparator } from \"@usevyre/react\"","subcomponents":["BreadcrumbItem","BreadcrumbLink","BreadcrumbSeparator"],"props":{},"antiPatterns":[{"pattern":"Using plain <a> tags inside Breadcrumb","reason":"Use BreadcrumbLink for correct styling and accessibility","fix":"Use BreadcrumbItem > BreadcrumbLink for each crumb"}],"examples":[{"description":"Basic breadcrumb","code":"<Breadcrumb>\n  <BreadcrumbItem><BreadcrumbLink href=\"/\">Home</BreadcrumbLink></BreadcrumbItem>\n  <BreadcrumbSeparator />\n  <BreadcrumbItem><BreadcrumbLink href=\"/docs\">Docs</BreadcrumbLink></BreadcrumbItem>\n  <BreadcrumbSeparator />\n  <BreadcrumbItem aria-current=\"page\">Button</BreadcrumbItem>\n</Breadcrumb>"}]},"Button":{"description":"Triggers actions and navigation. The most commonly used interactive element.","import":"import { Button } from \"@usevyre/react\"","props":{"variant":{"type":"enum","values":["primary","secondary","ghost","accent","teal","danger"],"default":"secondary","description":"Visual style. primary=high contrast CTA, secondary=bordered, ghost=minimal, accent=amber brand, teal=secondary accent, danger=destructive"},"size":{"type":"enum","values":["sm","md","lg","icon"],"default":"md","description":"Size scale. Use 'icon' for square icon-only buttons"},"loading":{"type":"boolean","default":false,"description":"Shows spinner and disables interaction"},"disabled":{"type":"boolean","default":false,"description":"Disables the button"},"as":{"type":"React.ElementType","default":"\"button\"","description":"Render as different element (e.g. 'a' for link buttons)"},"leftIcon":{"type":"ReactNode","description":"Icon rendered before the label"},"rightIcon":{"type":"ReactNode","description":"Icon rendered after the label"}},"accessibility":{"notes":["Always add aria-label when using size='icon' (no visible text)"]},"antiPatterns":[{"pattern":"variant=\"blue\"","reason":"No 'blue' variant exists","fix":"Use variant=\"accent\" for brand amber, or variant=\"teal\" for teal"},{"pattern":"size=\"xl\"","reason":"Maximum size is 'lg'","fix":"Use size=\"lg\""},{"pattern":"color=\"...\"","reason":"No color prop exists on Button","fix":"Use variant prop instead"},{"pattern":"icon={...}","reason":"No 'icon' prop for inserting icons","fix":"Use leftIcon={...} or rightIcon={...}"},{"pattern":"size=\"icon\" without aria-label","reason":"Icon-only buttons have no visible text — screen readers need aria-label","fix":"Add aria-label describing the action"},{"pattern":"padding / margin / marginTop (any spacing prop) on a useVyre component","reason":"Components have NO spacing props by design — internal spacing is fixed by tokens for visual consistency","fix":"Space BETWEEN components with <Stack gap> / <Grid gap>; space AROUND a block with <Box padding/margin> wrapping it"}],"examples":[{"description":"Primary CTA","code":"<Button variant=\"primary\">Get Started</Button>"},{"description":"Large accent button","code":"<Button variant=\"accent\" size=\"lg\">Launch App</Button>"},{"description":"Loading state","code":"<Button variant=\"danger\" loading>Deleting...</Button>"},{"description":"Link button","code":"<Button as=\"a\" href=\"/docs\" variant=\"secondary\">Read Docs</Button>"},{"description":"Icon-only button","code":"<Button variant=\"ghost\" size=\"icon\" aria-label=\"Close\">\n  <X size={16} />\n</Button>"}]},"Calendar":{"description":"Inline date-grid widget (always visible, no input). mode: single | range | multiple, optional time picker. For an input + popover use DatePicker; for start/end ranges with presets use DateRangePicker.","import":"import { Calendar } from \"@usevyre/react\"","props":{"value":{"type":"Date | null","description":"Currently selected date (controlled)"},"onChange":{"type":"function","description":"Callback when a date is selected"},"disabled":{"type":"boolean","default":false},"defaultMonth":{"type":"Date","description":"Month to display initially when value is empty (uncontrolled view). Used by DateRangePicker for the second month."}},"antiPatterns":[{"pattern":"Calendar for an input field that opens a popover","reason":"Calendar renders an always-visible grid, not a trigger","fix":"Use <DatePicker /> (single date) or <DateRangePicker /> (range)"},{"pattern":"value as tuple for mode=\"single\"","reason":"value type must match mode: Date for single, [Date,Date] for range, Date[] for multiple","fix":"Pass value matching mode; use mode=\"range\" for [start,end]"}],"examples":[{"description":"Controlled date picker","code":"const [date, setDate] = useState(null);\n<Calendar value={date} onChange={setDate} />"}]},"DatePicker":{"description":"Input trigger that opens a Calendar in a popover. Same modes as Calendar (single | range | multiple) plus a placeholder. Use this for a compact date field; use Calendar for an always-visible grid, or DateRangePicker for start/end ranges with presets.","import":"import { DatePicker } from \"@usevyre/react\"","props":{"value":{"type":"Date | [Date, Date] | Date[] | null","description":"Selected value (controlled). Type must match mode."},"onChange":{"type":"function","description":"Callback when the selection changes; argument shape matches mode"},"mode":{"type":"enum","values":["single","range","multiple"],"default":"single","description":"Selection mode"},"placeholder":{"type":"string","default":"Pick a date","description":"Trigger text when nothing is selected"},"showTime":{"type":"boolean","default":false,"description":"Adds an HH:MM time picker (single mode)"},"minDate":{"type":"Date","description":"Earliest selectable date"},"maxDate":{"type":"Date","description":"Latest selectable date"},"disabled":{"type":"function","description":"(date: Date) => boolean — disable specific dates"},"weekStartsOn":{"type":"enum","values":[0,1],"default":1,"description":"0 = Sunday, 1 = Monday"},"inputClassName":{"type":"string","description":"Class on the trigger button"}},"antiPatterns":[{"pattern":"DatePicker mode=\"range\" for { from, to } object","reason":"DatePicker range mode emits a [Date, Date] tuple, not a { from, to } object","fix":"Use <DateRangePicker /> for the { from, to } object API + presets + dual month"},{"pattern":"DatePicker without value/onChange","reason":"DatePicker is controlled — it has no internal selected state","fix":"Provide value and onChange (e.g. from useState)"}],"examples":[{"description":"Single date field","code":"const [date, setDate] = useState(null);\n<DatePicker value={date} onChange={setDate} placeholder=\"Pick a date\" />"},{"description":"Date + time","code":"<DatePicker value={date} onChange={setDate} showTime />"}]},"Card":{"description":"Content container with optional header, body, and footer sections.","import":"import { Card, CardHeader, CardBody, CardFooter } from \"@usevyre/react\"","subcomponents":["CardHeader","CardBody","CardFooter"],"props":{"variant":{"type":"enum","values":["default","elevated","outlined","ghost","accent"],"default":"default","description":"Visual style of the card"},"hoverable":{"type":"boolean","default":false,"description":"Adds hover lift effect"},"clickable":{"type":"boolean","default":false,"description":"Adds cursor pointer and active press feedback"}},"antiPatterns":[{"pattern":"variant=\"primary\"","reason":"Card has no 'primary' variant","fix":"Use variant=\"elevated\" | \"outlined\" | \"ghost\" | \"accent\""},{"pattern":"padding / margin / marginTop (any spacing prop) on a useVyre component","reason":"Components have NO spacing props by design — internal spacing is fixed by tokens for visual consistency","fix":"Space BETWEEN components with <Stack gap> / <Grid gap>; space AROUND a block with <Box padding/margin> wrapping it"}],"examples":[{"description":"Elevated card with sections","code":"<Card variant=\"elevated\">\n  <CardHeader><Badge variant=\"teal\">New</Badge></CardHeader>\n  <CardBody>\n    <h3>Card Title</h3>\n    <p>Description text.</p>\n  </CardBody>\n  <CardFooter>\n    <Button variant=\"ghost\" size=\"sm\">Learn more</Button>\n  </CardFooter>\n</Card>"}]},"Checkbox":{"description":"Binary toggle for boolean form values.","import":"import { Checkbox } from \"@usevyre/react\"","props":{"size":{"type":"enum","values":["sm","md"],"default":"md"},"checked":{"type":"boolean","description":"Controlled checked state"},"onCheckedChange":{"type":"function","description":"Called with the new boolean checked state"},"disabled":{"type":"boolean","default":false},"indeterminate":{"type":"boolean","default":false,"description":"Shows dash icon for partial selection state"}},"antiPatterns":[{"pattern":"size=\"lg\"","reason":"Maximum size is 'md'","fix":"Use size=\"md\""}],"examples":[{"description":"Labeled checkbox","code":"<label style={{ display: 'flex', alignItems: 'center', gap: 'var(--vyre-spacing-2)' }}>\n  <Checkbox checked={agreed} onCheckedChange={setAgreed} />\n  I agree to the terms\n</label>"}]},"RadioGroup":{"description":"Controlled single-choice group. RadioGroup owns the selected value; render it data-driven via the options array OR with composable <Radio> children for custom content. role=radiogroup with proper labelling. For multi-select use Checkbox; for a compact dropdown use Select.","import":"import { RadioGroup, Radio } from \"@usevyre/react\"","subcomponents":["Radio"],"props":{"value":{"type":"string","description":"Selected value (controlled). Vue: v-model."},"defaultValue":{"type":"string","description":"Initial value (uncontrolled, React only)"},"onChange":{"type":"function","description":"(value: string) => void. Vue: update:modelValue / v-model."},"name":{"type":"string","description":"Radio input name; auto-generated if omitted"},"disabled":{"type":"boolean","default":false,"description":"Disable the whole group"},"size":{"type":"enum","values":["sm","md"],"default":"md","description":"Control size"},"orientation":{"type":"enum","values":["vertical","horizontal"],"default":"vertical","description":"Layout direction"},"options":{"type":"{ value: string; label?: string; description?: string; disabled?: boolean }[]","description":"Data-driven options. Omit to pass <Radio> children instead."}},"antiPatterns":[{"pattern":"<Radio> used outside a <RadioGroup>","reason":"Radio reads selection + name from RadioGroup context; it throws without a provider","fix":"Always wrap <Radio> in <RadioGroup>"},{"pattern":"RadioGroup without value/onChange (React) or v-model (Vue)","reason":"RadioGroup is controlled; selection won't update","fix":"Bind value + onChange (React) or v-model (Vue); or defaultValue for uncontrolled in React"},{"pattern":"Using Checkbox for mutually-exclusive choices","reason":"Radio expresses single-choice semantics + keyboard model","fix":"Use RadioGroup + Radio (or options) for one-of-many"}],"examples":[{"description":"Data-driven","code":"<RadioGroup\n  value={plan}\n  onChange={setPlan}\n  options={[\n    { value: \"free\", label: \"Free\", description: \"For hobby projects\" },\n    { value: \"pro\",  label: \"Pro\",  description: \"For teams\" },\n  ]}\n/>"},{"description":"Composable children","code":"<RadioGroup value={plan} onChange={setPlan} orientation=\"horizontal\">\n  <Radio value=\"free\" label=\"Free\" />\n  <Radio value=\"pro\"  label=\"Pro\" />\n</RadioGroup>"}]},"RichTextEditor":{"description":"Controlled WYSIWYG editor. value is an HTML string; you own it in state and set it in onChange (React) / v-model (Vue). Native contentEditable + execCommand — zero dependencies. Toolbar: bold, italic, underline, strike, h1-h3, ordered/unordered lists, quote, code block, link, clear formatting.","import":"import { RichTextEditor } from \"@usevyre/react\"","props":{"value":{"type":"string","description":"HTML content (controlled). React: value + onChange. Vue: v-model."},"onChange":{"type":"function","description":"(html: string) => void. Vue: update:modelValue / v-model."},"placeholder":{"type":"string","default":"Write something…","description":"Shown when the editor is empty"},"disabled":{"type":"boolean","default":false,"description":"Not editable, dimmed; toolbar disabled"},"readOnly":{"type":"boolean","default":false,"description":"Not editable; toolbar hidden entirely"},"toolbar":{"type":"RichTextTool[]","description":"Which buttons to show. Default = all. Tools: \"bold\"|\"italic\"|\"underline\"|\"strike\"|\"h1\"|\"h2\"|\"h3\"|\"ul\"|\"ol\"|\"quote\"|\"code\"|\"link\"|\"clear\""},"minHeight":{"type":"string","default":"10rem","description":"CSS min-height of the editable area"},"sanitize":{"type":"function","description":"(html: string) => string. Optional sanitizer run on render-in AND emit-out. The component is zero-dependency and does NOT sanitize untrusted HTML by itself — pass your own (e.g. DOMPurify.sanitize) for untrusted content. The link tool always blocks javascript:/data:/vbscript: URLs."}},"antiPatterns":[{"pattern":"RichTextEditor without value/onChange (React) or v-model (Vue)","reason":"It is fully controlled; edits won't persist","fix":"Keep the HTML string in state and update it in onChange / v-model"},{"pattern":"Binding untrusted HTML to value without the sanitize prop","reason":"value is rendered as raw HTML (innerHTML) — stored XSS risk","fix":"Pass sanitize={DOMPurify.sanitize} (or sanitize before storing) for untrusted content"},{"pattern":"Rendering value as text or with dangerouslySetInnerHTML elsewhere without sanitising","reason":"value is raw HTML the user typed","fix":"Sanitise (e.g. DOMPurify) before re-rendering untrusted RTE output"},{"pattern":"toolbar=\"bold\" (string)","reason":"toolbar is an array of tool ids","fix":"Pass an array, e.g. toolbar={[\"bold\",\"italic\",\"link\"]}"}],"examples":[{"description":"Controlled editor","code":"const [html, setHtml] = useState(\"<p>Hello <strong>world</strong></p>\");\n<RichTextEditor value={html} onChange={setHtml} placeholder=\"Write…\" />"},{"description":"Minimal toolbar","code":"<RichTextEditor\n  value={html}\n  onChange={setHtml}\n  toolbar={[\"bold\", \"italic\", \"link\"]}\n/>"}]},"Command":{"description":"Command palette / search dialog. Use for search-first navigation or quick actions.","import":"import { Command, CommandInput, CommandList, CommandEmpty, CommandGroup, CommandItem, CommandDialog } from \"@usevyre/react\"","subcomponents":["CommandInput","CommandList","CommandEmpty","CommandGroup","CommandItem","CommandDialog"],"props":{},"antiPatterns":[{"pattern":"Using Input type=\"search\" for search UI","reason":"Command component is the correct pattern for search-first UI","fix":"Use Command + CommandInput + CommandList + CommandItem"}],"examples":[{"description":"Basic command palette","code":"<Command>\n  <CommandInput placeholder=\"Search...\" />\n  <CommandList>\n    <CommandEmpty>No results found.</CommandEmpty>\n    <CommandGroup heading=\"Suggestions\">\n      <CommandItem onSelect={() => handleSelect('dashboard')}>Dashboard</CommandItem>\n      <CommandItem onSelect={() => handleSelect('settings')}>Settings</CommandItem>\n    </CommandGroup>\n  </CommandList>\n</Command>"}]},"DropdownMenu":{"description":"Contextual menu triggered by a button. Supports items, separators, checkbox items, radio groups, and sub-menus.","import":"import { DropdownMenu, DropdownItem, DropdownSeparator, DropdownCheckboxItem, DropdownRadioGroup, DropdownRadioItem, DropdownSub } from \"@usevyre/react\"","subcomponents":["DropdownItem","DropdownSeparator","DropdownCheckboxItem","DropdownRadioGroup","DropdownRadioItem","DropdownSub"],"props":{"trigger":{"type":"ReactElement","description":"Element that opens the dropdown when clicked"}},"itemProps":{"variant":{"type":"enum","values":["default","danger"],"default":"default","description":"Use 'danger' for destructive actions"}},"antiPatterns":[{"pattern":"DropdownItem variant=\"primary\"","reason":"DropdownItem only has 'default' and 'danger' variants","fix":"Use variant=\"danger\" for destructive items only"}],"examples":[{"description":"Dropdown with danger item","code":"<DropdownMenu trigger={<Button variant=\"secondary\">Options</Button>}>\n  <DropdownItem onSelect={() => handleEdit()}>Edit</DropdownItem>\n  <DropdownItem onSelect={() => handleDuplicate()}>Duplicate</DropdownItem>\n  <DropdownSeparator />\n  <DropdownItem variant=\"danger\" onSelect={() => handleDelete()}>Delete</DropdownItem>\n</DropdownMenu>"}]},"Field":{"description":"Form field wrapper. Two ways to use it (both supported): (1) props-based — pass label/hint/state/required for the common case; (2) composable — use the parts FieldLabel, FieldDescription, FieldError, FieldGroup, FieldSet for richer layouts (multiple controls, custom error placement). The props-based API is unchanged and still works.","import":"import { Field, Input, Textarea } from \"@usevyre/react\"","props":{"label":{"type":"string","description":"Visible field label"},"hint":{"type":"string","description":"Helper or error text below the input"},"state":{"type":"enum","values":["idle","error","success","warning"],"default":"idle","description":"Validation state — affects border color and hint text color"},"required":{"type":"boolean","default":false,"description":"Shows required indicator"}},"antiPatterns":[{"pattern":"Applying state prop directly to Input","reason":"state belongs on Field, not on the Input itself","fix":"Wrap Input in <Field state=\"error\"> to apply validation styling"},{"pattern":"Mixing props label/hint AND FieldLabel/FieldError for the same field","reason":"Duplicates the label / message","fix":"Pick one: either props-based (label/hint/state) OR composable parts"}],"examples":[{"description":"Error state field","code":"<Field label=\"Email\" state=\"error\" hint=\"Invalid email format\">\n  <Input type=\"email\" placeholder=\"you@example.com\" />\n</Field>"},{"description":"Search field with left icon","code":"<Field label=\"Search\">\n  <Input leftElement={<SearchIcon />} placeholder=\"Search...\" />\n</Field>"},{"description":"Composable field with explicit parts","code":"<Field>\n  <FieldLabel required htmlFor=\"email\">Email</FieldLabel>\n  <Input id=\"email\" type=\"email\" />\n  <FieldDescription>We\\u2019ll never share it.</FieldDescription>\n  <FieldError>{errors.email}</FieldError>\n</Field>\n\n// Two controls side by side\n<FieldGroup orientation=\"horizontal\">\n  <Field label=\"First name\"><Input /></Field>\n  <Field label=\"Last name\"><Input /></Field>\n</FieldGroup>"}],"subcomponents":["FieldLabel","FieldDescription","FieldError","FieldGroup","FieldSet"]},"Input":{"description":"Text input field. Wrap in Field for labels and validation. Use leftElement/rightElement for icons.","import":"import { Input } from \"@usevyre/react\"","props":{"modelValue":{"type":"string | number","description":"Vue only: enables v-model (two-way binding). React: use native value + onChange. Native input attrs (type, placeholder, disabled…) work in both."},"size":{"type":"enum","values":["sm","md","lg"],"default":"md","description":"Height and text size scale. Note: 'icon' size is NOT valid for Input"},"leftElement":{"type":"ReactNode","description":"Icon or element rendered inside the input on the left"},"rightElement":{"type":"ReactNode","description":"Icon or element rendered inside the input on the right"}},"antiPatterns":[{"pattern":"size=\"icon\"","reason":"'icon' size is only valid for Button, not Input","fix":"Use size=\"sm\" | \"md\" | \"lg\""},{"pattern":"type=\"search\" for search UI","reason":"Use Command component for search-first interfaces","fix":"Import Command from @usevyre/react for search palettes"},{"pattern":"Vue: binding Input/Textarea value without v-model","reason":"Vue Input & Textarea support v-model (modelValue); manual :value alone won't update","fix":"Use v-model on <Input>/<Textarea> in Vue; in React use value + onChange"},{"pattern":"padding / margin / marginTop (any spacing prop) on a useVyre component","reason":"Components have NO spacing props by design — internal spacing is fixed by tokens for visual consistency","fix":"Space BETWEEN components with <Stack gap> / <Grid gap>; space AROUND a block with <Box padding/margin> wrapping it"}],"examples":[{"description":"Password input with icon","code":"<Input type=\"password\" rightElement={<EyeIcon />} placeholder=\"Password\" />"}]},"Label":{"description":"Accessible form label. Associate with input via htmlFor.","import":"import { Label } from \"@usevyre/react\"","props":{"htmlFor":{"type":"string","description":"ID of the associated input element"},"required":{"type":"boolean","default":false}},"examples":[{"description":"Label with input","code":"<Label htmlFor=\"email\">Email address</Label>\n<Input id=\"email\" type=\"email\" />"}]},"Modal":{"description":"Dialog overlay for confirmations, forms, or focused content.","import":"import { Modal, ModalHeader, ModalBody, ModalFooter } from \"@usevyre/react\"","subcomponents":["ModalHeader","ModalBody","ModalFooter"],"props":{"open":{"type":"boolean","description":"Controls visibility (controlled mode)"},"onClose":{"type":"function","description":"Called when modal is dismissed"},"size":{"type":"enum","values":["sm","md","lg","full"],"default":"md","description":"Width of the modal dialog"}},"antiPatterns":[{"pattern":"size=\"xl\"","reason":"Maximum size is 'full'","fix":"Use size=\"lg\" or size=\"full\""}],"examples":[{"description":"Confirmation modal","code":"<Modal open={isOpen} onClose={() => setIsOpen(false)} size=\"sm\">\n  <ModalHeader>Confirm Delete</ModalHeader>\n  <ModalBody>Are you sure you want to delete this item?</ModalBody>\n  <ModalFooter>\n    <Button variant=\"ghost\" onClick={() => setIsOpen(false)}>Cancel</Button>\n    <Button variant=\"danger\" onClick={handleDelete}>Delete</Button>\n  </ModalFooter>\n</Modal>"}]},"Pagination":{"description":"Page navigation for paginated lists or tables.","import":"import { Pagination } from \"@usevyre/react\"","props":{"page":{"type":"number","description":"Current page (1-indexed)"},"totalPages":{"type":"number","description":"Total number of pages"},"onPageChange":{"type":"function","description":"Called with the new page number when the user navigates"}},"examples":[{"description":"Basic pagination","code":"<Pagination page={currentPage} totalPages={totalPages} onPageChange={setCurrentPage} />"}]},"Popover":{"description":"Floating content panel anchored to a trigger element. For simple labels use Tooltip instead.","import":"import { Popover } from \"@usevyre/react\"","props":{"trigger":{"type":"ReactElement","description":"Element that opens the popover"},"placement":{"type":"enum","values":["top","top-start","top-end","bottom","bottom-start","bottom-end","left","left-start","left-end","right","right-start","right-end"],"default":"bottom","description":"Preferred placement relative to trigger"},"open":{"type":"boolean","description":"Controlled open state"},"onOpenChange":{"type":"function","description":"Callback when open state changes"},"closeOnOutside":{"type":"boolean","default":true,"description":"Close when clicking outside"}},"antiPatterns":[{"pattern":"placement=\"top-center\"","reason":"No 'top-center' — center alignment is the default when no suffix is given","fix":"Use placement=\"top\" for centered placement"}],"examples":[{"description":"Popover with custom content","code":"<Popover trigger={<Button variant=\"secondary\">More info</Button>} placement=\"bottom-start\">\n  <div style={{ padding: 'var(--vyre-spacing-4)' }}>\n    <p>Detailed information here.</p>\n  </div>\n</Popover>"}]},"Progress":{"description":"Visual progress indicator for tasks, uploads, or completion status.","import":"import { Progress } from \"@usevyre/react\"","props":{"value":{"type":"number","description":"Progress value (0–100)"},"size":{"type":"enum","values":["sm","md","lg"],"default":"md","description":"Height of the progress bar"},"variant":{"type":"enum","values":["default","accent","teal","success","danger"],"default":"default","description":"Color variant"}},"antiPatterns":[{"pattern":"value > 100","reason":"Value is clamped to 0–100","fix":"Normalize your value to 0–100 range before passing"}],"examples":[{"description":"Upload progress","code":"<Progress value={uploadPercent} variant=\"accent\" size=\"sm\" />"}]},"Select":{"description":"Dropdown for selecting one option from a list.","import":"import { Select } from \"@usevyre/react\"","props":{"options":{"type":"SelectOption[]","description":"Array of { value: string, label: string } objects"},"value":{"type":"string","description":"Controlled selected value"},"onChange":{"type":"function","description":"Called with new value string on selection"},"size":{"type":"enum","values":["sm","md","lg"],"default":"md"},"placeholder":{"type":"string","description":"Placeholder text when no value is selected"},"disabled":{"type":"boolean","default":false},"disablePortal":{"type":"boolean","default":false,"description":"Render the dropdown inline instead of teleporting it to <body>. Default false: the dropdown portals to body so it stays visible inside Modal / overflow:hidden containers"}},"antiPatterns":[{"pattern":"Passing strings directly as children","reason":"Select uses options prop, not children","fix":"Pass options={[{ value: 'a', label: 'Option A' }]}"}],"examples":[{"description":"Controlled select","code":"<Select\n  options={[{ value: 'react', label: 'React' }, { value: 'vue', label: 'Vue' }]}\n  value={framework}\n  onChange={setFramework}\n  placeholder=\"Choose framework\"\n/>"}]},"Separator":{"description":"Horizontal or vertical divider line.","import":"import { Separator } from \"@usevyre/react\"","props":{"orientation":{"type":"enum","values":["horizontal","vertical"],"default":"horizontal"}},"examples":[{"description":"Horizontal separator","code":"<Separator />"},{"description":"Vertical separator","code":"<Separator orientation=\"vertical\" />"}]},"Sheet":{"description":"Side panel (drawer) that slides in from the edge. For forms, detail views, or settings.","import":"import { Sheet, SheetHeader, SheetBody, SheetFooter } from \"@usevyre/react\"","subcomponents":["SheetHeader","SheetBody","SheetFooter"],"props":{"open":{"type":"boolean","description":"Controls visibility"},"onClose":{"type":"function","description":"Called when sheet is dismissed"},"size":{"type":"enum","values":["sm","md","lg","full"],"default":"md","description":"Width of the sheet panel"},"side":{"type":"enum","values":["left","right"],"default":"right","description":"Which edge the sheet slides from"}},"examples":[{"description":"Settings sheet from the right","code":"<Sheet open={isOpen} onClose={() => setIsOpen(false)} side=\"right\">\n  <SheetHeader>Settings</SheetHeader>\n  <SheetBody>Settings content here.</SheetBody>\n  <SheetFooter>\n    <Button variant=\"accent\">Save</Button>\n  </SheetFooter>\n</Sheet>"}]},"Sidebar":{"description":"App navigation sidebar. Use AppLayout as the root layout wrapper.","import":"import { AppLayout, Sidebar, SidebarHeader, SidebarContent, SidebarSection, SidebarItem, SidebarFooter } from \"@usevyre/react\"","subcomponents":["AppLayout","SidebarHeader","SidebarContent","SidebarSection","SidebarItem","SidebarFooter","SidebarTrigger"],"props":{"variant":{"type":"enum","values":["default","floating"],"default":"default"},"SidebarTrigger.icon":{"type":"ReactNode","description":"Icon shown when the sidebar is expanded. Optional — defaults to the built-in menu icon. Vue: #icon slot."},"SidebarTrigger.collapsedIcon":{"type":"ReactNode","description":"Icon shown when the sidebar is collapsed. Optional — falls back to icon, then the built-in icon. Vue: #collapsed-icon slot. Use a different glyph here to signal collapsed state (common UX pattern)."}},"examples":[{"description":"App layout with sidebar","code":"<AppLayout>\n  <Sidebar>\n    <SidebarHeader>Logo</SidebarHeader>\n    <SidebarContent>\n      <SidebarSection heading=\"Main\">\n        <SidebarItem href=\"/\" active>Dashboard</SidebarItem>\n        <SidebarItem href=\"/settings\">Settings</SidebarItem>\n      </SidebarSection>\n    </SidebarContent>\n    <SidebarFooter><Avatar fallback=\"JD\" size=\"sm\" /></SidebarFooter>\n  </Sidebar>\n  <main>Page content</main>\n</AppLayout>"},{"description":"SidebarTrigger with distinct open/collapsed icons","code":"<SidebarTrigger icon={<PanelLeftClose />} collapsedIcon={<PanelLeftOpen />} />\n\n// Vue:\n// <SidebarTrigger>\n//   <template #icon><PanelLeftClose /></template>\n//   <template #collapsed-icon><PanelLeftOpen /></template>\n// </SidebarTrigger>"}],"antiPatterns":[{"pattern":"Vue: passing icon/collapsedIcon as props on SidebarTrigger","reason":"Vue SidebarTrigger customises icons via slots, not props (consistent with SidebarItem)","fix":"Use <template #icon> and <template #collapsed-icon>; React uses icon / collapsedIcon props"}]},"Skeleton":{"description":"Loading placeholder that mimics the shape of content while data loads.","import":"import { Skeleton } from \"@usevyre/react\"","props":{"variant":{"type":"enum","values":["rect","circle","text"],"default":"rect","description":"Shape of the skeleton. 'circle' for avatars, 'text' for text lines, 'rect' for blocks"},"width":{"type":"string | number","description":"Width (e.g. '200px' or '100%')"},"height":{"type":"string | number","description":"Height (e.g. '20px' or 40)"}},"examples":[{"description":"Avatar skeleton","code":"<Skeleton variant=\"circle\" width={40} height={40} />"},{"description":"Text line skeletons","code":"<Skeleton variant=\"text\" width=\"100%\" />\n<Skeleton variant=\"text\" width=\"60%\" />"}]},"Slider":{"description":"Range input for selecting a numeric value within a range.","import":"import { Slider } from \"@usevyre/react\"","props":{"value":{"type":"number","description":"Controlled value"},"onValueChange":{"type":"function","description":"Called with the new numeric value"},"min":{"type":"number","default":0},"max":{"type":"number","default":100},"step":{"type":"number","default":1},"size":{"type":"enum","values":["sm","md"],"default":"md"},"disabled":{"type":"boolean","default":false}},"examples":[{"description":"Volume slider","code":"<Slider value={volume} onValueChange={setVolume} min={0} max={100} step={5} />"}]},"Switch":{"description":"Toggle switch for boolean on/off settings.","import":"import { Switch } from \"@usevyre/react\"","props":{"checked":{"type":"boolean","description":"Controlled checked state"},"onCheckedChange":{"type":"function","description":"Called with the new boolean checked state"},"size":{"type":"enum","values":["sm","md"],"default":"md"},"disabled":{"type":"boolean","default":false}},"examples":[{"description":"Notifications toggle","code":"<label style={{ display: 'flex', alignItems: 'center', gap: 'var(--vyre-spacing-2)' }}>\n  <Switch checked={notifications} onCheckedChange={setNotifications} />\n  Enable notifications\n</label>"}]},"Table":{"description":"Data table with optional sorting. Compose with TableHeader, TableRow, TableCell.","import":"import { Table, TableHead, TableBody, TableRow, TableHeader, TableCell } from \"@usevyre/react\"","subcomponents":["TableHead","TableBody","TableRow","TableHeader","TableCell"],"props":{},"examples":[{"description":"Basic data table","code":"<Table>\n  <TableHead>\n    <TableRow>\n      <TableHeader>Name</TableHeader>\n      <TableHeader>Status</TableHeader>\n    </TableRow>\n  </TableHead>\n  <TableBody>\n    <TableRow>\n      <TableCell>Alice</TableCell>\n      <TableCell><Badge variant=\"success\">Active</Badge></TableCell>\n    </TableRow>\n  </TableBody>\n</Table>"}]},"Tabs":{"description":"Tabbed navigation for switching between content panels.","import":"import { Tabs, TabList, Tab, TabPanels, TabPanel } from \"@usevyre/react\"","subcomponents":["TabList","Tab","TabPanels","TabPanel"],"props":{"defaultValue":{"type":"string","description":"Initial active tab value (uncontrolled)"},"value":{"type":"string","description":"Active tab value (controlled)"},"onChange":{"type":"function","description":"Called with new index when tab changes"}},"examples":[{"description":"Basic tabs","code":"<Tabs defaultValue=\"overview\">\n  <TabList>\n    <Tab value=\"overview\">Overview</Tab>\n    <Tab value=\"settings\">Settings</Tab>\n  </TabList>\n  <TabPanels>\n    <TabPanel value=\"overview\">Overview content</TabPanel>\n    <TabPanel value=\"settings\">Settings content</TabPanel>\n  </TabPanels>\n</Tabs>"}]},"Toast":{"description":"Transient notification. Use the useToast hook to trigger toasts imperatively. React: wrap app in <ToastProvider>. Vue: place <ToastViewport /> once in app root.","import":"import { useToast, ToastProvider } from \"@usevyre/react\" // Vue: import { useToast, ToastViewport } from \"@usevyre/vue\"","props":{"variant":{"type":"enum","values":["default","success","warning","danger"],"default":"default","description":"Color and icon of the toast"},"title":{"type":"string","description":"Bold heading text"},"description":{"type":"string","description":"Supporting detail text"},"duration":{"type":"number","default":4000,"description":"Auto-dismiss time in milliseconds"}},"antiPatterns":[{"pattern":"Rendering <Toast> directly in JSX","reason":"Toast is triggered via the useToast hook, not rendered directly","fix":"Use: const { toast } = useToast(); then toast({ title, variant })"},{"pattern":"variant=\"error\"","reason":"No 'error' variant","fix":"Use variant=\"danger\""},{"pattern":"variant=\"info\"","reason":"No 'info' variant on Toast","fix":"Use variant=\"default\""}],"examples":[{"description":"Trigger a success toast","code":"const { toast } = useToast();\n\n<Button onClick={() => toast({ title: 'Saved!', variant: 'success', duration: 3000 })}>\n  Save\n</Button>"},{"description":"Setup: wrap app with ToastProvider","code":"<ToastProvider>\n  <App />\n</ToastProvider>"}]},"Tooltip":{"description":"Short label that appears on hover/focus. For rich content use Popover instead.","import":"import { Tooltip } from \"@usevyre/react\"","props":{"content":{"type":"string | ReactNode","description":"Text or element shown in the tooltip"},"placement":{"type":"enum","values":["top","bottom","left","right"],"default":"top"},"delay":{"type":"number","default":300,"description":"Delay in ms before tooltip appears"},"disablePortal":{"type":"boolean","default":false,"description":"Render the tooltip inline instead of teleporting it to <body>. Default false: the tooltip portals to body so it stays visible inside Modal / overflow:hidden containers"}},"antiPatterns":[{"pattern":"Using Tooltip for rich content (forms, buttons, etc.)","reason":"Tooltip is for short text labels only","fix":"Use Popover for rich interactive content"}],"examples":[{"description":"Tooltip on an icon button","code":"<Tooltip content=\"Close dialog\" placement=\"bottom\">\n  <Button variant=\"ghost\" size=\"icon\" aria-label=\"Close\">\n    <X size={16} />\n  </Button>\n</Tooltip>"}]},"Typography":{"description":"Text rendering components with semantic scale. Includes Text, Heading, Lead, Code, Blockquote.","import":"import { Text, Heading, Lead, Code, Blockquote } from \"@usevyre/react\"","subcomponents":["Text","Heading","Lead","Code","Blockquote"],"textProps":{"size":{"type":"enum","values":["xs","sm","md","lg","xl"],"default":"md"}},"headingProps":{"size":{"type":"enum","values":["xs","sm","md","lg","xl","2xl","3xl"],"default":"lg"},"as":{"type":"enum","values":["h1","h2","h3","h4","h5","h6"],"default":"h2"}},"antiPatterns":[{"pattern":"Using raw <h1>, <p> tags instead of Typography components","reason":"Typography components apply the correct token-based styles","fix":"Use <Heading>, <Text>, <Lead> from @usevyre/react"}],"examples":[{"description":"Page heading and body text","code":"<Heading size=\"2xl\" as=\"h1\">Dashboard</Heading>\n<Lead>Welcome back. Here's what's happening today.</Lead>\n<Text size=\"sm\" style={{ color: 'var(--vyre-color-semantic-text-muted)' }}>Last updated 5 minutes ago.</Text>"}]},"ButtonGroup":{"description":"Groups multiple Button components into one visual unit (toolbar, segmented control). Pure layout — no internal state.","import":"import { ButtonGroup, Button } from \"@usevyre/react\"","props":{"orientation":{"type":"enum","values":["horizontal","vertical"],"default":"horizontal","description":"Layout direction of grouped buttons"},"attached":{"type":"boolean","default":false,"description":"Remove gap so buttons share collapsed borders (segmented control look)"},"size":{"type":"enum","values":["sm","md","lg","icon"],"description":"Size forwarded to all child buttons"}},"antiPatterns":[{"pattern":"ButtonGroup variant=\"...\"","reason":"ButtonGroup has no variant prop — variant goes on each child Button","fix":"Set variant on each <Button> inside the group"},{"pattern":"ButtonGroup without Button children","reason":"ButtonGroup is a layout wrapper for Button elements","fix":"Place <Button> elements as direct children"}],"examples":[{"description":"Segmented control","code":"<ButtonGroup attached>\n  <Button variant=\"secondary\">Day</Button>\n  <Button variant=\"secondary\">Week</Button>\n  <Button variant=\"secondary\">Month</Button>\n</ButtonGroup>"},{"description":"Vertical group","code":"<ButtonGroup orientation=\"vertical\" attached>\n  <Button variant=\"secondary\">Top</Button>\n  <Button variant=\"secondary\">Bottom</Button>\n</ButtonGroup>"}]},"TagsInput":{"description":"Multi-tag input. Type and press Enter or comma to add a tag, click x to remove, Backspace on empty input removes the last tag. Controlled.","import":"import { TagsInput } from \"@usevyre/react\"","props":{"value":{"type":"string[]","description":"Controlled list of tags (required)"},"onChange":{"type":"(tags: string[]) => void","description":"Called with the new tag array on every change. React only — Vue uses v-model"},"placeholder":{"type":"string","description":"Input placeholder, hidden when max is reached"},"disabled":{"type":"boolean","default":false,"description":"Disables all interaction"},"max":{"type":"number","description":"Maximum number of tags; input is disabled when reached"},"size":{"type":"enum","values":["sm","md","lg"],"default":"md","description":"Size scale"}},"antiPatterns":[{"pattern":"TagsInput value={string}","reason":"value must be a string array, not a string","fix":"Pass an array: value={['react','vue']}"},{"pattern":"TagsInput without onChange","reason":"TagsInput is controlled — it needs onChange to update","fix":"Provide value and onChange (React) or v-model (Vue)"}],"examples":[{"description":"Basic tags input","code":"const [tags, setTags] = useState<string[]>([]);\n<TagsInput value={tags} onChange={setTags} placeholder=\"Add a tag…\" />"},{"description":"Limited to 5 tags","code":"<TagsInput value={tags} onChange={setTags} max={5} />"}]},"Combobox":{"description":"Searchable single-select dropdown with typeahead filtering and keyboard navigation. Use when the list is long enough to need search. Differs from Select (no search) and Command (palette).","import":"import { Combobox } from \"@usevyre/react\"","props":{"options":{"type":"{ value: string; label: string; disabled?: boolean }[]","description":"Selectable options (required)"},"value":{"type":"string | null","description":"Controlled selected value; null clears selection (required)"},"onChange":{"type":"(value: string | null) => void","description":"Called when selection changes. React only — Vue uses v-model"},"placeholder":{"type":"string","default":"\"Search…\"","description":"Input placeholder when nothing is selected"},"disabled":{"type":"boolean","default":false,"description":"Disables the combobox"},"size":{"type":"enum","values":["sm","md","lg"],"default":"md","description":"Height scale"},"emptyText":{"type":"string","default":"\"No results\"","description":"Text shown when search matches no options"},"disablePortal":{"type":"boolean","default":false,"description":"Render the dropdown inline instead of teleporting it to <body>. Default false: the dropdown portals to body so it stays visible inside Modal / overflow:hidden containers"}},"antiPatterns":[{"pattern":"Combobox value=\"\"","reason":"Empty selection must be null, not empty string","fix":"Use value={null} for no selection"},{"pattern":"Combobox options={string[]}","reason":"options must be objects with value and label","fix":"Use [{ value: 'ts', label: 'TypeScript' }]"},{"pattern":"Using Combobox for command palette","reason":"Combobox is single-value select, not an action palette","fix":"Use Command for command palettes"}],"examples":[{"description":"Searchable language picker","code":"const [lang, setLang] = useState<string | null>(null);\n<Combobox\n  options={[{ value: \"ts\", label: \"TypeScript\" }, { value: \"go\", label: \"Go\" }]}\n  value={lang}\n  onChange={setLang}\n  placeholder=\"Search language…\"\n/>"}]},"DataGrid":{"description":"Table with built-in column sorting, loading skeletons, and empty state. Filtering and pagination are out of scope — compose with the Pagination component.","import":"import { DataGrid } from \"@usevyre/react\"","props":{"columns":{"type":"{ key: string; label: string; sortable?: boolean; width?: string }[]","description":"Column definitions (required)"},"rows":{"type":"Record<string, unknown>[]","description":"Row data; each object keyed by column key (required)"},"sortKey":{"type":"string","description":"Controlled active sort column key"},"sortDir":{"type":"enum","values":["asc","desc"],"description":"Controlled sort direction"},"onSort":{"type":"(key: string, dir: 'asc' | 'desc') => void","description":"Called when a sortable header is clicked. React only — Vue emits sort + v-model:sortKey/sortDir"},"loading":{"type":"boolean","default":false,"description":"Show skeleton placeholder rows"},"emptyText":{"type":"string","default":"\"No data\"","description":"Message shown when rows is empty"},"stickyHeader":{"type":"boolean","default":false,"description":"Keep the header visible while scrolling"}},"antiPatterns":[{"pattern":"DataGrid expecting built-in pagination","reason":"DataGrid does not paginate — it only sorts","fix":"Slice rows yourself and use the Pagination component"},{"pattern":"DataGrid expecting built-in filtering","reason":"DataGrid does not filter rows","fix":"Filter the rows array before passing it in"},{"pattern":"sortable without onSort","reason":"Sorting is controlled — the grid does not sort data itself","fix":"Handle onSort and sort the rows array in your state"}],"examples":[{"description":"Sortable grid","code":"const cols = [{ key: \"name\", label: \"Name\", sortable: true }];\n<DataGrid\n  columns={cols}\n  rows={people}\n  sortKey={sortKey}\n  sortDir={sortDir}\n  onSort={(k, d) => { setSortKey(k); setSortDir(d); }}\n/>"},{"description":"Loading state","code":"<DataGrid columns={cols} rows={[]} loading />"}]},"Tag":{"description":"Standalone display tag/chip for categories, labels, or filter chips. NOT an input — for tag input use TagsInput. Group multiple with TagGroup.","import":"import { Tag } from \"@usevyre/react\"","props":{"variant":{"type":"enum","values":["default","accent","danger"],"default":"default","description":"Visual style. default=neutral, accent=brand, danger=destructive/error"},"size":{"type":"enum","values":["sm","md","lg"],"default":"md","description":"Size scale"},"onRemove":{"type":"() => void","description":"React only. When provided, renders a × remove button. Vue: use `removable` prop + @remove event"},"onClick":{"type":"() => void","description":"React only. When provided, makes the whole tag interactive (keyboard accessible). Vue: use `clickable` prop + @click event"},"disabled":{"type":"boolean","default":false,"description":"Disables interaction (only relevant with onClick/onRemove)"}},"antiPatterns":[{"pattern":"Tag variant=\"success\"","reason":"Tag only has default, accent, danger variants (unlike Badge which has more)","fix":"Use Badge for success/warning/teal status colors; Tag is for categories/filters"},{"pattern":"Using Tag for tag input","reason":"Tag is display-only, it does not accept typed input","fix":"Use TagsInput for adding/removing tags via keyboard"},{"pattern":"Tag size=\"xl\"","reason":"Maximum size is 'lg'","fix":"Use size=\"lg\""}],"examples":[{"description":"Category tags in a group","code":"<TagGroup>\n  <Tag>Design</Tag>\n  <Tag variant=\"accent\">Featured</Tag>\n  <Tag>Engineering</Tag>\n</TagGroup>"},{"description":"Removable filter chip (React)","code":"<Tag onRemove={() => removeFilter(\"react\")}>react</Tag>"},{"description":"Clickable toggle tag (React)","code":"<Tag onClick={() => toggleFilter(\"vue\")}>vue</Tag>"}]},"TagGroup":{"description":"Read-only container that lays out multiple Tag elements with automatic wrapping and consistent spacing. For tag input use TagsInput.","import":"import { TagGroup, Tag } from \"@usevyre/react\"","props":{"gap":{"type":"enum","values":["sm","md","lg"],"default":"md","description":"Spacing between tags"},"wrap":{"type":"boolean","default":true,"description":"Wrap tags onto multiple lines when they overflow; set false for single-line scroll"}},"antiPatterns":[{"pattern":"TagGroup without Tag children","reason":"TagGroup is a layout wrapper for Tag elements","fix":"Place <Tag> elements as direct children"},{"pattern":"Using TagGroup for tag input","reason":"TagGroup is display-only","fix":"Use TagsInput for an editable tag field"}],"examples":[{"description":"Tag group with mixed variants","code":"<TagGroup gap=\"sm\">\n  <Tag>React</Tag>\n  <Tag>Vue</Tag>\n  <Tag variant=\"accent\">TypeScript</Tag>\n</TagGroup>"}]},"Item":{"description":"Layout primitive for list rows, settings rows, and notification rows. Denser than Card — use Item (not Card) for repeated list rows.","import":"import { Item, ItemMedia, ItemContent, ItemTitle, ItemDescription, ItemActions, ItemGroup } from \"@usevyre/react\"","subcomponents":["ItemGroup","ItemMedia","ItemContent","ItemTitle","ItemDescription","ItemActions"],"props":{"variant":{"type":"enum","values":["default","outlined","muted","plain"],"default":"default","description":"Visual style of the row. plain = transparent + no border (use when composing Item inside another surface like Card or a Kanban card to avoid a double background)."},"size":{"type":"enum","values":["sm","md","lg"],"default":"md","description":"Vertical density / text size of the row"},"clickable":{"type":"boolean","default":false,"description":"Adds pointer cursor, hover background, focus ring, and role=button"}},"antiPatterns":[{"pattern":"Card used for repeated list rows","reason":"Card is a content container; Item is the dense list-row primitive","fix":"Use <Item> (optionally inside <ItemGroup separated>) for list/settings rows"},{"pattern":"Item variant=\"primary\"","reason":"Item has no 'primary' variant","fix":"Use variant=\"default\" | \"outlined\" | \"muted\""},{"pattern":"raw text directly inside Item","reason":"Item lays out media/content/actions columns; bare text breaks alignment","fix":"Wrap text in <ItemContent><ItemTitle>…</ItemTitle></ItemContent>"}],"examples":[{"description":"Settings row with media, content and a trailing switch","code":"<Item>\n  <ItemMedia><BellIcon /></ItemMedia>\n  <ItemContent>\n    <ItemTitle>Notifications</ItemTitle>\n    <ItemDescription>Receive an email when someone mentions you.</ItemDescription>\n  </ItemContent>\n  <ItemActions>\n    <Switch defaultChecked />\n  </ItemActions>\n</Item>"},{"description":"Grouped clickable list with dividers","code":"<ItemGroup separated>\n  <Item clickable>\n    <ItemContent><ItemTitle>Profile</ItemTitle></ItemContent>\n  </Item>\n  <Item clickable>\n    <ItemContent><ItemTitle>Billing</ItemTitle></ItemContent>\n  </Item>\n</ItemGroup>"}]},"Kanban":{"description":"Drag-and-drop board: cards move between columns (or reorder within a column). CONTROLLED & data-driven like DataGrid. While dragging, a placeholder shows the exact drop position. Each card is wrapped in a Card (variant=\"outlined\"); renderCard (React) / #card slot (Vue) can render ANY content incl. complex components (Avatar/Badge/Progress). Columns and cards accept an optional semantic color tint. Native HTML5 DnD, zero deps.","import":"import { Kanban } from \"@usevyre/react\"","props":{"value":{"type":"KanbanColumn[]","description":"Controlled board data. KanbanColumn = { id, title, cards: KanbanCard[], color? }; KanbanCard = { id, title, description?, color? }. Extra app fields may ride along on cards and be read in renderCard. color = \"default\"|\"accent\"|\"teal\"|\"success\"|\"warning\"|\"danger\" (token-based tint). Card ids must be unique across the whole board."},"onChange":{"type":"function","description":"(next: KanbanColumn[]) => void — called with the next columns array after a drag move. Required; set it back into your state."},"renderCard":{"type":"function","description":"(card, column) => ReactNode — custom card body, rendered inside the wrapping <Card>. Vue: #card scoped slot. Can return any components (Avatar, Badge, Progress, etc.); attach extra fields to the card object and read them here."},"onCardClick":{"type":"function","description":"(card, column) => void — fired on click/Enter/Space (not after a drag). Vue: @card-click."}},"antiPatterns":[{"pattern":"Kanban without onChange (or ignoring it)","reason":"Kanban holds no internal data state; dropped cards won't move unless you apply onChange","fix":"Store columns in state and setColumns in onChange (v-model in Vue)"},{"pattern":"Duplicate card ids across columns","reason":"Card moves are resolved by id; duplicates corrupt the move","fix":"Use globally-unique card ids across the entire board"},{"pattern":"Mutating value in place then calling onChange","reason":"React/Vue need a new array reference to re-render reliably","fix":"Pass the new array Kanban gives you straight to setState / v-model"},{"pattern":"color=\"blue\" (or any non-semantic value)","reason":"color is a fixed semantic set, not an arbitrary CSS color","fix":"Use one of: \"default\" | \"accent\" | \"teal\" | \"success\" | \"warning\" | \"danger\""}],"examples":[{"description":"Controlled board","code":"const [columns, setColumns] = useState([\n  { id: \"todo\",  title: \"To Do\",       cards: [{ id: \"1\", title: \"Spec API\" }] },\n  { id: \"doing\", title: \"In Progress\", cards: [] },\n  { id: \"done\",  title: \"Done\",        cards: [{ id: \"2\", title: \"Kickoff\" }] },\n]);\n<Kanban value={columns} onChange={setColumns} />"},{"description":"Custom card body + click handler","code":"<Kanban\n  value={columns}\n  onChange={setColumns}\n  onCardClick={(card) => openDetail(card.id)}\n  renderCard={(card) => (\n    <><strong>{card.title}</strong><Badge>{card.id}</Badge></>\n  )}\n/>"},{"description":"Tinted columns/cards + complex card content","code":"const [cols, setCols] = useState([\n  { id: \"doing\", title: \"In Progress\", color: \"teal\", cards: [\n    { id: \"t1\", title: \"OAuth\", assignee: \"AK\", progress: 60, color: \"warning\" },\n  ]},\n]);\n<Kanban\n  value={cols}\n  onChange={setCols}\n  renderCard={(card) => (\n    <><strong>{card.title}</strong><Progress value={card.progress} /></>\n  )}\n/>"}]},"Conversation":{"description":"Chat / inbox message thread. CONTROLLED & data-driven like Kanban — you own `value` (messages array) and append in your own send handler; Conversation holds no message state. Consecutive messages from the same author are grouped (avatar + name shown once), day separators are inserted on date change, and outgoing messages (authorId === currentUserId) align right.","import":"import { Conversation } from \"@usevyre/react\"","props":{"value":{"type":"ConversationMessage[]","description":"Ordered messages. ConversationMessage = { id, authorId, text?, authorName?, authorAvatar?, timestamp?: Date|string|number, status?: \"sending\"|\"sent\"|\"delivered\"|\"read\", attachments?: ConversationAttachment[] }. ConversationAttachment = { kind: \"image\"|\"audio\"|\"video\"|\"file\", url, name?, size? } — rendered inside the bubble. Required & controlled."},"currentUserId":{"type":"string","description":"Whose messages are outgoing (aligned right). Required — match against message.authorId."},"composer":{"type":"boolean","default":false,"description":"Show the built-in input + Send button. Pair with onSend."},"onSend":{"type":"function","description":"(text: string, files: File[]) => void — called when the built-in composer submits. files holds anything staged via the attach button (empty array unless allowAttachments). You own the upload + turning staged files into message attachments. Vue: @send."},"placeholder":{"type":"string","default":"Write a message…","description":"Composer input placeholder."},"typing":{"type":"boolean | string","default":false,"description":"Show an incoming typing indicator. Pass a string to label it."},"allowAttachments":{"type":"boolean","default":false,"description":"Show a 📎 attach button + staged-file chips in the built-in composer. Files come back via onSend's second arg."},"accept":{"type":"string","description":"Forwarded to the file input's accept attribute, e.g. \"image/*\"."},"renderMessage":{"type":"function","description":"(message, meta) => ReactNode — custom bubble body. meta = { outgoing, isGroupStart, isGroupEnd }. Vue: #message scoped slot."},"renderComposer":{"type":"function","description":"(api) => ReactNode — replace the composer entirely. api = { value, setValue, files, setFiles, send }. Vue: #composer scoped slot."}},"antiPatterns":[{"pattern":"Conversation without currentUserId","reason":"Alignment (incoming vs outgoing) is decided by authorId === currentUserId","fix":"Always pass currentUserId matching one of the message authorId values"},{"pattern":"Expecting Conversation to store/append messages","reason":"Conversation is controlled & stateless for data, like Kanban/DataGrid","fix":"Append to your own state in onSend (or @send) and pass it back via value"},{"pattern":"composer without onSend (React) / @send (Vue)","reason":"The built-in composer emits text; nothing happens unless you handle it","fix":"Provide onSend / @send to append the message to value"},{"pattern":"Treating onSend as (text) only when using allowAttachments","reason":"With allowAttachments, staged files arrive as the 2nd arg; ignoring it drops attachments","fix":"Handle onSend(text, files) — map files to message attachments and append"}],"examples":[{"description":"Controlled thread with built-in composer","code":"const [messages, setMessages] = useState([\n  { id: \"1\", authorId: \"sam\", authorName: \"Sam\", text: \"Hey!\" },\n  { id: \"2\", authorId: \"me\", text: \"Hi \\ud83d\\udc4b\", status: \"read\" },\n]);\n<Conversation\n  value={messages}\n  currentUserId=\"me\"\n  composer\n  onSend={(t) => setMessages((m) => [...m, { id: crypto.randomUUID(), authorId: \"me\", text: t }])}\n/>"},{"description":"Typing indicator + custom bubble","code":"<Conversation\n  value={messages}\n  currentUserId=\"me\"\n  typing=\"Sam is typing\"\n  renderMessage={(m) => <strong>{m.text}</strong>}\n/>"},{"description":"Message with image + file attachments","code":"const messages = [\n  { id: \"1\", authorId: \"sam\", authorName: \"Sam\", text: \"Moodboard \\ud83d\\udc47\",\n    attachments: [{ kind: \"image\", url: \"/board.png\", name: \"board.png\" }] },\n  { id: \"2\", authorId: \"me\", text: \"Specs:\", status: \"read\",\n    attachments: [{ kind: \"file\", url: \"/spec.pdf\", name: \"spec.pdf\", size: \"2.4 MB\" }] },\n];\n<Conversation value={messages} currentUserId=\"me\" />"}]},"Stack":{"description":"Full one-dimensional flex layout primitive. USE INSTEAD OF <div style={{display:'flex'}}>. Covers the whole CSS flexbox surface (direction incl. reverse, wrap, align/justify/alignContent/alignSelf, grow/shrink/basis, per-axis gap) with token-locked spacing. Renders a plain <div> (or `as`).","import":"import { Stack } from \"@usevyre/react\"","props":{"direction":{"type":"enum","values":["row","column","row-reverse","column-reverse"],"default":"row","description":"flex-direction"},"inline":{"type":"boolean","default":false,"description":"Render as inline-flex instead of flex"},"gap":{"type":"enum","values":["none","xs","sm","md","lg","xl","2xl"],"default":"md","description":"Space between children. Maps to --vyre-spacing tokens. NEVER a raw px/rem value."},"rowGap":{"type":"enum","values":["none","xs","sm","md","lg","xl","2xl"],"description":"Row-gap override. Maps to --vyre-spacing tokens. NEVER a raw px/rem value."},"columnGap":{"type":"enum","values":["none","xs","sm","md","lg","xl","2xl"],"description":"Column-gap override. Maps to --vyre-spacing tokens. NEVER a raw px/rem value."},"align":{"type":"enum","values":["start","center","end","stretch","baseline"],"default":"stretch","description":"align-items (cross axis)"},"justify":{"type":"enum","values":["start","center","end","between","around","evenly"],"default":"start","description":"justify-content (main axis)"},"alignContent":{"type":"enum","values":["start","center","end","stretch","between","around","evenly"],"description":"align-content (multi-line cross axis)"},"alignSelf":{"type":"enum","values":["auto","start","center","end","stretch","baseline"],"description":"align-self for this element"},"wrap":{"type":"enum","values":["nowrap","wrap","wrap-reverse"],"default":"nowrap","description":"flex-wrap"},"grow":{"type":"number","description":"flex-grow"},"shrink":{"type":"number","description":"flex-shrink"},"basis":{"type":"enum","values":["none","xs","sm","md","lg","xl","2xl","auto","content","0"],"description":"flex-basis — token, 'auto', 'content', or '0'"},"width":{"type":"enum","values":["auto","full","fit","screen","xs","sm","md","lg","xl","2xl"],"description":"Width — keyword (auto/full=100%/fit=fit-content/screen) or a fixed-rem token size (xs 8 · sm 12 · md 16 · lg 24 · xl 32 · 2xl 42). Avoids an inline width style."},"height":{"type":"enum","values":["auto","full","fit","screen","xs","sm","md","lg","xl","2xl"],"description":"Height — keyword (auto/full=100%/fit=fit-content/screen) or a fixed-rem token size (xs 8 · sm 12 · md 16 · lg 24 · xl 32 · 2xl 42). Avoids an inline height style."},"as":{"type":"string","default":"div","description":"HTML tag to render"}},"antiPatterns":[{"pattern":"<div style={{ display: 'flex', gap: 12 }}>","reason":"Inline flex styles bypass the design system and use magic-number spacing","fix":"Use <Stack gap=\"md\"> — gap is a token"},{"pattern":"gap={12} or gap=\"12px\"","reason":"Stack gap is a closed token enum","fix":"Use gap=\"none|xs|sm|md|lg|xl|2xl\""},{"pattern":"direction=\"vertical\" / \"horizontal\"","reason":"Stack mirrors CSS flex-direction names","fix":"Use direction=\"row\" or \"column\" (also row-reverse / column-reverse)"},{"pattern":"style={{ width: \"100%\" }} / style={{ height: 320 }}","reason":"Inline width/height bypass the design system and use magic numbers","fix":"Use the width / height prop: width=\"full\", width=\"md\", height=\"screen\", etc."}],"examples":[{"description":"Row, vertically centered, spaced apart","code":"<Stack direction=\"row\" gap=\"md\" align=\"center\" justify=\"between\">\n  <Avatar src={user.avatar} />\n  <Text>{user.name}</Text>\n  <Button>Edit</Button>\n</Stack>"},{"description":"Wrapping grid-ish gallery with per-axis gap","code":"<Stack wrap=\"wrap\" rowGap=\"lg\" columnGap=\"md\">\n  {tags.map((t) => <Tag key={t}>{t}</Tag>)}\n</Stack>"}]},"Grid":{"description":"Two-dimensional CSS grid primitive. Explicit column/row counts (or auto-fit), auto-flow control, token gap. Pair with GridItem for cell spanning/placement. Renders a plain <div> (or `as`).","import":"import { Grid, GridItem } from \"@usevyre/react\"","subcomponents":["GridItem"],"props":{"columns":{"type":"number | \"auto-fit\"","default":1,"description":"Equal-width column count (1-12), or 'auto-fit' for responsive wrapping"},"rows":{"type":"number | \"auto\"","description":"Explicit row count, or 'auto'"},"flow":{"type":"enum","values":["row","column","dense","row-dense","column-dense"],"description":"grid-auto-flow"},"gap":{"type":"enum","values":["none","xs","sm","md","lg","xl","2xl"],"default":"md","description":"Space between cells. Maps to --vyre-spacing tokens. NEVER a raw px/rem value."},"rowGap":{"type":"enum","values":["none","xs","sm","md","lg","xl","2xl"],"description":"Row-gap override. Maps to --vyre-spacing tokens. NEVER a raw px/rem value."},"columnGap":{"type":"enum","values":["none","xs","sm","md","lg","xl","2xl"],"description":"Column-gap override. Maps to --vyre-spacing tokens. NEVER a raw px/rem value."},"align":{"type":"enum","values":["start","center","end","stretch"],"default":"stretch","description":"align-items"},"justify":{"type":"enum","values":["start","center","end","stretch"],"description":"justify-items"},"width":{"type":"enum","values":["auto","full","fit","screen","xs","sm","md","lg","xl","2xl"],"description":"Width — keyword (auto/full=100%/fit=fit-content/screen) or a fixed-rem token size (xs 8 · sm 12 · md 16 · lg 24 · xl 32 · 2xl 42). Avoids an inline width style."},"height":{"type":"enum","values":["auto","full","fit","screen","xs","sm","md","lg","xl","2xl"],"description":"Height — keyword (auto/full=100%/fit=fit-content/screen) or a fixed-rem token size (xs 8 · sm 12 · md 16 · lg 24 · xl 32 · 2xl 42). Avoids an inline height style."},"as":{"type":"string","default":"div","description":"HTML tag to render"}},"antiPatterns":[{"pattern":"<div style={{ display:'grid', gridTemplateColumns:'1fr 1fr 1fr' }}>","reason":"Inline grid styles bypass the design system","fix":"Use <Grid columns={3} gap=\"md\">"},{"pattern":"columns=\"3\" (string)","reason":"columns is a number or the literal 'auto-fit'","fix":"Use columns={3} or columns=\"auto-fit\""},{"pattern":"Nested div with inline grid-column for spanning","reason":"Spanning has a dedicated primitive","fix":"Wrap the cell in <GridItem colSpan={2}>"},{"pattern":"style={{ width: \"100%\" }} / style={{ height: 320 }}","reason":"Inline width/height bypass the design system and use magic numbers","fix":"Use the width / height prop: width=\"full\", width=\"md\", height=\"screen\", etc."}],"examples":[{"description":"Three-column grid with a wide first cell","code":"<Grid columns={3} gap=\"lg\">\n  <GridItem colSpan={2}><Card>Wide</Card></GridItem>\n  <Card>Two</Card>\n  <Card>Three</Card>\n</Grid>"},{"description":"Responsive auto-fit grid","code":"<Grid columns=\"auto-fit\" gap=\"md\">\n  {items.map((i) => <Card key={i.id}>{i.title}</Card>)}\n</Grid>"}]},"GridItem":{"description":"Child placement inside <Grid>. Sets column/row span and start lines. Renders a plain <div> (or `as`).","import":"import { GridItem } from \"@usevyre/react\"","props":{"colSpan":{"type":"number","description":"Number of columns this item spans"},"rowSpan":{"type":"number","description":"Number of rows this item spans"},"colStart":{"type":"number","description":"1-based column line to start at"},"rowStart":{"type":"number","description":"1-based row line to start at"},"as":{"type":"string","default":"div","description":"HTML tag to render"}},"antiPatterns":[{"pattern":"GridItem outside a Grid","reason":"GridItem only has effect as a direct child of Grid","fix":"Place <GridItem> directly inside <Grid>"}],"examples":[{"description":"Span two columns","code":"<Grid columns={4} gap=\"md\">\n  <GridItem colSpan={2}>Featured</GridItem>\n  <div>a</div>\n  <div>b</div>\n</Grid>"}]},"Box":{"description":"Spacing-only container plus a controlled escape hatch. Token padding/margin with shorthand, per-axis (X/Y) and per-side (Top/Right/Bottom/Left) overrides. The `style` prop is an explicit anti-pattern escape hatch. Renders a plain <div> (or `as`).","import":"import { Box } from \"@usevyre/react\"","props":{"padding":{"type":"enum","values":["none","xs","sm","md","lg","xl","2xl"],"description":"Inner spacing, all sides. Maps to --vyre-spacing tokens. NEVER a raw px/rem value."},"paddingX":{"type":"enum","values":["none","xs","sm","md","lg","xl","2xl"],"description":"Inner spacing, left + right. Maps to --vyre-spacing tokens. NEVER a raw px/rem value."},"paddingY":{"type":"enum","values":["none","xs","sm","md","lg","xl","2xl"],"description":"Inner spacing, top + bottom. Maps to --vyre-spacing tokens. NEVER a raw px/rem value."},"paddingTop":{"type":"enum","values":["none","xs","sm","md","lg","xl","2xl"],"description":"Inner spacing, top. Maps to --vyre-spacing tokens. NEVER a raw px/rem value."},"paddingRight":{"type":"enum","values":["none","xs","sm","md","lg","xl","2xl"],"description":"Inner spacing, right. Maps to --vyre-spacing tokens. NEVER a raw px/rem value."},"paddingBottom":{"type":"enum","values":["none","xs","sm","md","lg","xl","2xl"],"description":"Inner spacing, bottom. Maps to --vyre-spacing tokens. NEVER a raw px/rem value."},"paddingLeft":{"type":"enum","values":["none","xs","sm","md","lg","xl","2xl"],"description":"Inner spacing, left. Maps to --vyre-spacing tokens. NEVER a raw px/rem value."},"margin":{"type":"enum","values":["none","xs","sm","md","lg","xl","2xl"],"description":"Outer spacing, all sides. Maps to --vyre-spacing tokens. NEVER a raw px/rem value."},"marginX":{"type":"enum","values":["none","xs","sm","md","lg","xl","2xl"],"description":"Outer spacing, left + right. Maps to --vyre-spacing tokens. NEVER a raw px/rem value."},"marginY":{"type":"enum","values":["none","xs","sm","md","lg","xl","2xl"],"description":"Outer spacing, top + bottom. Maps to --vyre-spacing tokens. NEVER a raw px/rem value."},"marginTop":{"type":"enum","values":["none","xs","sm","md","lg","xl","2xl"],"description":"Outer spacing, top. Maps to --vyre-spacing tokens. NEVER a raw px/rem value."},"marginRight":{"type":"enum","values":["none","xs","sm","md","lg","xl","2xl"],"description":"Outer spacing, right. Maps to --vyre-spacing tokens. NEVER a raw px/rem value."},"marginBottom":{"type":"enum","values":["none","xs","sm","md","lg","xl","2xl"],"description":"Outer spacing, bottom. Maps to --vyre-spacing tokens. NEVER a raw px/rem value."},"marginLeft":{"type":"enum","values":["none","xs","sm","md","lg","xl","2xl"],"description":"Outer spacing, left. Maps to --vyre-spacing tokens. NEVER a raw px/rem value."},"width":{"type":"enum","values":["auto","full","fit","screen","xs","sm","md","lg","xl","2xl"],"description":"Width — keyword (auto/full=100%/fit=fit-content/screen) or a fixed-rem token size (xs 8 · sm 12 · md 16 · lg 24 · xl 32 · 2xl 42). Avoids an inline width style."},"height":{"type":"enum","values":["auto","full","fit","screen","xs","sm","md","lg","xl","2xl"],"description":"Height — keyword (auto/full=100%/fit=fit-content/screen) or a fixed-rem token size (xs 8 · sm 12 · md 16 · lg 24 · xl 32 · 2xl 42). Avoids an inline height style."},"as":{"type":"string","default":"div","description":"HTML tag to render"},"style":{"type":"React.CSSProperties","description":"ANTI-PATTERN escape hatch. Only for values the design system cannot express. Flagged by @usevyre/eslint-plugin."}},"antiPatterns":[{"pattern":"<Box style={{ padding: 16 }}>","reason":"padding is a token prop; style is a last resort","fix":"Use <Box padding=\"md\"> (or paddingX/paddingTop/...)"},{"pattern":"Using Box for flex/grid layout","reason":"Box is spacing-only and has no layout props","fix":"Use <Stack> or <Grid>"},{"pattern":"style={{ width: \"100%\" }} / style={{ height: 320 }}","reason":"Inline width/height bypass the design system and use magic numbers","fix":"Use the width / height prop: width=\"full\", width=\"md\", height=\"screen\", etc."}],"examples":[{"description":"Asymmetric padding","code":"<Box as=\"section\" paddingX=\"lg\" paddingY=\"md\">\n  <Heading>Settings</Heading>\n</Box>"},{"description":"Vertical rhythm via margin-top","code":"<Box marginTop=\"xl\"><Separator /></Box>"}]},"Form":{"description":"Controlled, data-driven form. Zero dependencies. Validation runs on submit and (after the first submit) on blur. Errors map into the wrapped Field automatically (state=error + hint=message). Compose with FormField, which wires name/value/onChange/onBlur into a single control child.","import":"import { Form, FormField } from \"@usevyre/react\"","subcomponents":["FormField"],"props":{"values":{"type":"Record<string, any>","description":"Controlled values map. Omit for uncontrolled (use defaultValues)."},"defaultValues":{"type":"Record<string, any>","description":"Initial values when uncontrolled"},"onChange":{"type":"function","description":"(values) => void — called whenever any field value changes"},"onSubmit":{"type":"function","description":"(values) => void | Promise<void> — called ONLY when the form is valid"},"onInvalid":{"type":"function","description":"(errors: Record<string,string>) => void — called when submitted but invalid"}},"antiPatterns":[{"pattern":"Manually tracking each field's error state with useState","reason":"Form already validates and maps errors into Field automatically","fix":"Wrap controls in <FormField name rules> and let Form manage errors"},{"pattern":"Adding a validation library (zod/yup) just for basic rules","reason":"Form ships zero-dependency built-in rules","fix":"Use rules={{ required, minLength, pattern, email, validate }}"},{"pattern":"<FormField> with multiple control children","reason":"FormField clones a single child to inject name/value/onChange","fix":"Use one control per FormField (Input/Textarea/Select/etc.)"},{"pattern":"<FormField> outside a <Form>","reason":"FormField reads form context","fix":"Always nest FormField inside <Form>"}],"examples":[{"description":"Controlled sign-in form with built-in rules","code":"const [values, setValues] = useState({ email: \"\", password: \"\" });\n\n<Form values={values} onChange={setValues} onSubmit={(v) => signIn(v)}>\n  <FormField name=\"email\" label=\"Email\" rules={{ required: true, email: true }}>\n    <Input type=\"email\" />\n  </FormField>\n  <FormField name=\"password\" label=\"Password\" rules={{ required: true, minLength: 8 }}>\n    <Input type=\"password\" />\n  </FormField>\n  <Button type=\"submit\" variant=\"primary\">Sign in</Button>\n</Form>"},{"description":"Custom cross-field validation","code":"<FormField\n  name=\"confirm\"\n  label=\"Confirm password\"\n  rules={{\n    required: true,\n    validate: (v, all) => v === all.password ? null : \"Passwords do not match\",\n  }}\n>\n  <Input type=\"password\" />\n</FormField>"}]},"FormField":{"description":"A single labelled, validated field inside <Form>. Injects name/value/onChange/onBlur into its one control child and wraps it in <Field> (label + error state + hint).","import":"import { FormField } from \"@usevyre/react\"","props":{"name":{"type":"string","description":"Key into the form's values map (required)"},"label":{"type":"string","description":"Label rendered by the wrapping Field"},"hint":{"type":"string","description":"Helper text shown when there is no error"},"rules":{"type":"object","description":"{ required?: boolean|string, minLength?, maxLength?, min?, max?: number, pattern?: RegExp, email?: boolean, validate?: (value, allValues) => string|null }"}},"antiPatterns":[{"pattern":"Putting onChange/value manually on the control inside FormField","reason":"FormField already injects them; manual props can desync from form state","fix":"Let FormField wire the control; only pass static props (type, placeholder)"}],"examples":[{"description":"Field with a hint","code":"<FormField name=\"bio\" label=\"Bio\" hint=\"Max 200 characters\" rules={{ maxLength: 200 }}>\n  <Textarea />\n</FormField>"}]},"NumberInput":{"description":"Controlled numeric input with −/+ stepper buttons. onChange emits a NUMBER (or null when empty) — NOT an event. Drops straight into <FormField> (Form handles the non-event value). Clamps to min/max on blur; keyboard ArrowUp/Down ±step, Shift+Arrow ±step×10.","import":"import { NumberInput } from \"@usevyre/react\"","props":{"value":{"type":"number | null","description":"Controlled value. null = empty. Omit for uncontrolled."},"defaultValue":{"type":"number | null","default":"null","description":"Initial value when uncontrolled"},"onChange":{"type":"function","description":"(value: number | null) => void — emits the parsed number, or null when empty"},"min":{"type":"number","description":"Minimum; value is clamped to this on blur"},"max":{"type":"number","description":"Maximum; value is clamped to this on blur"},"step":{"type":"number","default":1,"description":"Increment/decrement amount"},"precision":{"type":"number","description":"Decimal places to round to"},"size":{"type":"enum","values":["sm","md","lg"],"default":"md","description":"Control size"},"disabled":{"type":"boolean","default":false,"description":"Disable input and steppers"},"readOnly":{"type":"boolean","default":false,"description":"Read-only (no stepping/typing)"}},"antiPatterns":[{"pattern":"onChange={(e) => set(e.target.value)}","reason":"NumberInput emits a number, not an event — there is no e.target","fix":"onChange={(value) => set(value)} — value is number | null"},{"pattern":"Using <Input type=\"number\"> for numeric fields","reason":"Native number input has no token-styled stepper, no clamp, returns a string","fix":"Use <NumberInput value onChange min max step />"},{"pattern":"Parsing the value with Number() in form state","reason":"NumberInput already emits a real number (or null)","fix":"Store the value directly; it is already number | null"}],"examples":[{"description":"Quantity selector","code":"const [qty, setQty] = useState<number | null>(1);\n\n<NumberInput value={qty} onChange={setQty} min={1} max={99} />"},{"description":"Inside a Form","code":"<FormField name=\"age\" label=\"Age\" rules={{ required: true, min: 18 }}>\n  <NumberInput min={0} max={120} />\n</FormField>"}]},"ToggleGroup":{"description":"Segmented control. CONTROLLED — the group owns the value. onChange emits the VALUE (not an event). type=single → value:string|null; type=multiple → value:string[]. Provide options[] for simple lists or <ToggleItem value> children for custom content. Distinct from Switch (boolean), ButtonGroup (layout only), RadioGroup (form radios, single only).","import":"import { ToggleGroup, ToggleItem } from \"@usevyre/react\"","subcomponents":["ToggleItem"],"props":{"type":{"type":"enum","values":["single","multiple"],"default":"single","description":"single → value string|null; multiple → value string[]"},"value":{"type":"string | null | string[]","description":"Controlled selected value. string|null when single, string[] when multiple."},"onChange":{"type":"function","description":"(value) => void — emits string|null (single) or string[] (multiple). NOT an event."},"options":{"type":"array","description":"{ value: string; label?; icon?; disabled? }[] — alternative to ToggleItem children"},"size":{"type":"enum","values":["sm","md","lg"],"default":"md","description":"Control size"},"orientation":{"type":"enum","values":["horizontal","vertical"],"default":"horizontal","description":"Layout direction"},"disabled":{"type":"boolean","default":false,"description":"Disable the whole group"}},"antiPatterns":[{"pattern":"onChange={(e) => set(e.target.value)}","reason":"ToggleGroup emits the value, not an event","fix":"onChange={(value) => set(value)} — string|null (single) or string[] (multiple)"},{"pattern":"Using ToggleGroup for a single on/off setting","reason":"That is a boolean toggle","fix":"Use <Switch> for on/off; ToggleGroup is for choosing among options"},{"pattern":"type=\"multiple\" with a string value","reason":"multiple mode requires an array value","fix":"value={['a','b']} and onChange receives string[]"},{"pattern":"<ToggleItem> outside <ToggleGroup>","reason":"ToggleItem reads group context","fix":"Always nest ToggleItem inside ToggleGroup (or use options)"}],"examples":[{"description":"Single-select view switcher (options)","code":"const [view, setView] = useState<string | null>(\"grid\");\n\n<ToggleGroup\n  value={view}\n  onChange={setView}\n  options={[\n    { value: \"grid\", label: \"Grid\" },\n    { value: \"list\", label: \"List\" },\n  ]}\n/>"},{"description":"Multiple-select formatting (composable)","code":"const [fmt, setFmt] = useState<string[]>([\"bold\"]);\n\n<ToggleGroup type=\"multiple\" value={fmt} onChange={setFmt}>\n  <ToggleItem value=\"bold\">B</ToggleItem>\n  <ToggleItem value=\"italic\">I</ToggleItem>\n  <ToggleItem value=\"underline\">U</ToggleItem>\n</ToggleGroup>"}]},"ToggleItem":{"description":"A single toggle button inside <ToggleGroup>. Reads selection state from the group via context.","import":"import { ToggleItem } from \"@usevyre/react\"","props":{"value":{"type":"string","description":"This item's value (required)"},"icon":{"type":"ReactNode","description":"Optional leading icon"},"disabled":{"type":"boolean","default":false,"description":"Disable just this item"}},"antiPatterns":[{"pattern":"Tracking selected state on ToggleItem yourself","reason":"Selection is owned by ToggleGroup","fix":"Only set value; the group controls selected state"}],"examples":[{"description":"Composable items","code":"<ToggleGroup value={v} onChange={setV}>\n  <ToggleItem value=\"left\">Left</ToggleItem>\n  <ToggleItem value=\"center\">Center</ToggleItem>\n</ToggleGroup>"}]},"Stepper":{"description":"Multi-step flow indicator + controller (onboarding/checkout/wizard). CONTROLLED by a 0-based index. Compose StepperNav (with Step indicators) and StepPanel (content shown when its index == active). Step/StepPanel take an explicit 0-based `index`. Not Tabs — Stepper is an ORDERED linear flow with completed/current/upcoming states.","import":"import { Stepper, StepperNav, Step, StepPanel } from \"@usevyre/react\"","subcomponents":["StepperNav","Step","StepPanel"],"props":{"value":{"type":"number","description":"Controlled active step (0-based). Omit for uncontrolled."},"defaultValue":{"type":"number","default":0,"description":"Initial active step when uncontrolled"},"onChange":{"type":"function","description":"(index: number) => void — emits the new active index"},"orientation":{"type":"enum","values":["horizontal","vertical"],"default":"horizontal","description":"Layout direction"},"clickable":{"type":"boolean","default":false,"description":"Allow clicking a completed Step to jump back to it"}},"antiPatterns":[{"pattern":"Using Tabs for a wizard / checkout flow","reason":"Tabs are peer panels; a step flow is ordered with completed/current/upcoming state","fix":"Use <Stepper> with StepperNav + Step + StepPanel"},{"pattern":"onChange={(e) => set(e.target.value)}","reason":"Stepper emits the index number, not an event","fix":"onChange={(index) => setStep(index)}"},{"pattern":"Manually toggling which panel is visible","reason":"StepPanel renders itself only when its index === active","fix":"Give each StepPanel an index; Stepper shows the active one"},{"pattern":"<Step> or <StepPanel> outside <Stepper>","reason":"They read Stepper context","fix":"Nest Step inside StepperNav, StepPanel inside Stepper"}],"examples":[{"description":"Three-step wizard with Back/Next","code":"const [step, setStep] = useState(0);\n\n<Stepper value={step} onChange={setStep}>\n  <StepperNav>\n    <Step index={0} label=\"Account\" />\n    <Step index={1} label=\"Profile\" />\n    <Step index={2} label=\"Done\" />\n  </StepperNav>\n  <StepPanel index={0}><AccountForm /></StepPanel>\n  <StepPanel index={1}><ProfileForm /></StepPanel>\n  <StepPanel index={2}><Summary /></StepPanel>\n  <Stack direction=\"row\" gap=\"sm\" justify=\"between\">\n    <Button onClick={() => setStep((s) => s - 1)} disabled={step === 0}>Back</Button>\n    <Button variant=\"primary\" onClick={() => setStep((s) => s + 1)}>Next</Button>\n  </Stack>\n</Stepper>"},{"description":"Vertical with descriptions","code":"<Stepper orientation=\"vertical\" defaultValue={1}>\n  <StepperNav>\n    <Step index={0} label=\"Cart\" description=\"2 items\" />\n    <Step index={1} label=\"Shipping\" description=\"Enter address\" />\n    <Step index={2} label=\"Payment\" />\n  </StepperNav>\n</Stepper>"}]},"StepperNav":{"description":"Container for Step indicators inside <Stepper>. Lays them out per the Stepper's orientation.","import":"import { Stepper, StepperNav, Step, StepPanel } from \"@usevyre/react\"","props":{}},"Step":{"description":"One step indicator inside <StepperNav>. State (completed/current/upcoming) derives from the Stepper's active index automatically.","import":"import { Stepper, StepperNav, Step, StepPanel } from \"@usevyre/react\"","props":{"index":{"type":"number","description":"0-based position (required)"},"label":{"type":"ReactNode","description":"Step label"},"description":{"type":"ReactNode","description":"Secondary text under the label"},"icon":{"type":"ReactNode","description":"Custom indicator content (defaults to number, or ✓ when completed)"}}},"StepPanel":{"description":"Content for one step. Renders its children only when its index equals the Stepper's active step.","import":"import { Stepper, StepperNav, Step, StepPanel } from \"@usevyre/react\"","props":{"index":{"type":"number","description":"0-based position matching its Step (required)"}}},"EmptyState":{"description":"Presentational placeholder for empty lists, tables, and search results. No state. title/description/variant/size are props; the optional call-to-action goes in children (React) or the default slot (Vue). variant picks a preset icon (default=box, search=magnifier, error=warning); pass `icon` (or #icon slot) to override.","import":"import { EmptyState } from \"@usevyre/react\"","props":{"title":{"type":"string","description":"Headline (required)"},"description":{"type":"string","description":"Supporting text under the title"},"variant":{"type":"enum","values":["default","search","error"],"default":"default","description":"Preset icon: default=box, search=magnifier, error=warning"},"icon":{"type":"ReactNode","description":"Custom icon, overrides the variant preset"},"size":{"type":"enum","values":["sm","md","lg"],"default":"md","description":"sm for inline/in-Card, md default, lg for full-page"},"children":{"type":"ReactNode","description":"The call-to-action (a Button, or buttons in a Stack)"}},"antiPatterns":[{"pattern":"Building an empty placeholder with a bare <div> + centered text","reason":"Inconsistent spacing/typography; AI reinvents it each time","fix":"Use <EmptyState title description variant>"},{"pattern":"action / cta prop","reason":"There is no action prop; the CTA is composed","fix":"Put the Button as children of EmptyState"},{"pattern":"Using EmptyState for a loading state","reason":"EmptyState is for no-data, not in-progress","fix":"Use <Skeleton> while loading; EmptyState when the result set is empty"}],"examples":[{"description":"Empty search results with a reset CTA","code":"<EmptyState\n  variant=\"search\"\n  title=\"No results\"\n  description=\"Try a different search term.\"\n>\n  <Button variant=\"secondary\" onClick={reset}>Clear filters</Button>\n</EmptyState>"},{"description":"Full-page empty list","code":"<EmptyState\n  size=\"lg\"\n  title=\"No projects yet\"\n  description=\"Create your first project to get started.\"\n>\n  <Button variant=\"primary\">New project</Button>\n</EmptyState>"}]},"Stat":{"description":"Presentational dashboard KPI. No state. The arrow DIRECTION follows the sign of `delta` (the actual change: -0.4% → down arrow). The arrow/delta COLOR is set explicitly by `trend` (up=success, down=danger, neutral=muted) — so 'churn -0.4%, trend=up' shows a green DOWN arrow. Wrap several in StatGroup for an evenly-split row with dividers.","import":"import { Stat, StatGroup } from \"@usevyre/react\"","subcomponents":["StatGroup"],"props":{"label":{"type":"string","description":"Metric name (required)"},"value":{"type":"string | number","description":"The headline figure (required, rendered large)"},"delta":{"type":"string | number","description":"The change amount, e.g. \"+12%\" or 24. Its sign sets the arrow direction (+ up, - down, 0/none flat)."},"trend":{"type":"enum","values":["up","down","neutral"],"default":"neutral","description":"Sets only the COLOR — up=success, down=danger, neutral=muted. Does NOT set the arrow direction (that comes from delta's sign)."},"deltaLabel":{"type":"string","description":"Context for the delta, e.g. \"vs last month\""},"icon":{"type":"ReactNode","description":"Optional leading icon (Vue: #icon slot)"},"size":{"type":"enum","values":["sm","md","lg"],"default":"md","description":"Value size"}},"antiPatterns":[{"pattern":"Assuming trend flips the arrow direction","reason":"Arrow direction comes from the delta sign; trend only sets color","fix":"delta=\"-0.4%\" always shows a down arrow; trend=\"up\" just colors it green"},{"pattern":"Building a KPI card with Card + manual layout","reason":"Inconsistent value/label/delta styling; AI reinvents it","fix":"Use <Stat label value delta trend />"},{"pattern":"Laying out a KPI row with custom flex + dividers","reason":"StatGroup already splits evenly with dividers","fix":"Wrap the Stats in <StatGroup>"}],"examples":[{"description":"KPI row; note churn stays green while going down","code":"<StatGroup>\n  <Stat label=\"Revenue\" value=\"$48.2k\" delta=\"+12%\" trend=\"up\" deltaLabel=\"vs last month\" />\n  <Stat label=\"Churn\" value=\"2.1%\" delta=\"-0.4%\" trend=\"up\" deltaLabel=\"lower is better\" />\n  <Stat label=\"Orders\" value=\"1,204\" delta=\"0%\" trend=\"neutral\" />\n</StatGroup>"},{"description":"Single stat with icon","code":"<Stat label=\"Active users\" value=\"12,840\" delta=\"+3.2%\" trend=\"up\"\n      icon={<UsersIcon />} size=\"lg\" />"}]},"StatGroup":{"description":"Evenly-split row of <Stat> with subtle dividers between items. Each Stat flexes to equal width.","import":"import { Stat, StatGroup } from \"@usevyre/react\"","props":{},"antiPatterns":[{"pattern":"Putting non-Stat children in StatGroup","reason":"Dividers/equal-split styling target .vyre-stat","fix":"Only place <Stat> elements inside StatGroup"}],"examples":[{"description":"Three KPIs in a row","code":"<StatGroup>\n  <Stat label=\"MRR\" value=\"$9.6k\" delta=\"+5%\" trend=\"up\" />\n  <Stat label=\"Refunds\" value=\"32\" delta=\"+8\" trend=\"down\" />\n</StatGroup>"}]},"Timeline":{"description":"Vertical activity feed for audit logs and history. Presentational — a status dot per item plus a connector line. Pass `items` for plain logs, or TimelineItem children for rich per-item content. Timeline does NOT reorder; pass items in the order you want shown.","import":"import { Timeline, TimelineItem } from \"@usevyre/react\"","subcomponents":["TimelineItem"],"props":{"items":{"type":"array","description":"{ title, time?, description?, status?, icon? }[] — alternative to TimelineItem children"},"children":{"type":"ReactNode","description":"TimelineItem elements (use for rich content)"}},"antiPatterns":[{"pattern":"Building an activity log with a <ul> + manual dots/lines","reason":"Inconsistent markers/spacing; AI reinvents it each time","fix":"Use <Timeline items={[...]} /> or TimelineItem children"},{"pattern":"Using Stepper for a history/audit feed","reason":"Stepper is an ordered flow with completed/current/upcoming; a feed is just past events","fix":"Use <Timeline> for logs/history; Stepper for wizards"},{"pattern":"Expecting Timeline to sort by time","reason":"Timeline renders items in given order","fix":"Sort the array yourself (newest- or oldest-first)"}],"examples":[{"description":"Plain audit log via items","code":"<Timeline\n  items={[\n    { title: \"Deployed v2.1\", time: \"2m ago\", status: \"success\" },\n    { title: \"Build started\", time: \"5m ago\", status: \"info\" },\n    { title: \"Push to main\", time: \"6m ago\" },\n  ]}\n/>"},{"description":"Rich content via children","code":"<Timeline>\n  <TimelineItem title=\"Invoice paid\" time=\"Apr 2\" status=\"success\">\n    <Text size=\"sm\">$1,200 — <a href=\"#\">view receipt</a></Text>\n  </TimelineItem>\n  <TimelineItem title=\"Invoice sent\" time=\"Mar 28\" status=\"info\" />\n</Timeline>"}]},"TimelineItem":{"description":"One entry in a <Timeline>. Renders a status-colored dot (or a custom icon), a title, an optional time, and optional rich content.","import":"import { Timeline, TimelineItem } from \"@usevyre/react\"","props":{"title":{"type":"ReactNode","description":"Entry title (required)"},"time":{"type":"ReactNode","description":"Timestamp, right-aligned"},"status":{"type":"enum","values":["default","success","warning","danger","info"],"default":"default","description":"Colors the marker dot"},"icon":{"type":"ReactNode","description":"Custom marker, overrides the status dot (Vue: #icon slot)"},"children":{"type":"ReactNode","description":"Rich content under the title"}},"antiPatterns":[{"pattern":"<TimelineItem> outside <Timeline>","reason":"Marker/connector layout assumes the Timeline list context","fix":"Always nest TimelineItem inside Timeline"}],"examples":[{"description":"Item with rich content","code":"<TimelineItem title=\"Comment added\" time=\"1h ago\" status=\"default\">\n  <Text size=\"sm\">“Looks good to me 👍”</Text>\n</TimelineItem>"}]},"Tree":{"description":"Hierarchical tree view for file explorers and nested navigation. DATA-DRIVEN and CONTROLLED — pass a nested `data` array; the Tree renders recursively. Single selection. A node WITH children is a folder (click toggles expand); a leaf fires onSelect. Keyboard: ArrowUp/Down move, ArrowRight/Left expand/collapse, Enter/Space select.","import":"import { Tree } from \"@usevyre/react\"","props":{"data":{"type":"TreeNode[]","description":"Nested: { id: string; label: ReactNode; icon?: ReactNode; disabled?: boolean; children?: TreeNode[] }"},"expandedIds":{"type":"string[]","description":"Controlled set of expanded node ids. Omit for uncontrolled."},"defaultExpandedIds":{"type":"string[]","default":"[]","description":"Initially expanded ids when uncontrolled"},"onExpandedChange":{"type":"function","description":"(ids: string[]) => void"},"selectedId":{"type":"string | null","description":"Controlled selected node id. Omit for uncontrolled."},"defaultSelectedId":{"type":"string | null","default":"null","description":"Initial selection when uncontrolled"},"onSelect":{"type":"function","description":"(id: string) => void — fired on click/Enter/Space"}},"antiPatterns":[{"pattern":"Rendering a nested <ul> tree by hand with manual expand state","reason":"Reinvents recursion, keyboard nav, and a11y roles every time","fix":"Pass a nested `data` array to <Tree> and control expandedIds/selectedId"},{"pattern":"onSelect={(e) => ...}","reason":"Tree emits the node id, not an event","fix":"onSelect={(id) => setSelected(id)}"},{"pattern":"Mutating the data array to expand/collapse","reason":"Expansion is controlled via expandedIds, not the data","fix":"Track expandedIds in state (or use defaultExpandedIds)"},{"pattern":"Using DropdownMenu submenus for a file tree","reason":"Submenus are transient menus; a tree is persistent hierarchical content","fix":"Use <Tree> for file explorers / nested nav"}],"examples":[{"description":"File explorer, controlled selection","code":"const [sel, setSel] = useState<string | null>(\"src/a.ts\");\n\n<Tree\n  data={[\n    { id: \"src\", label: \"src\", children: [\n      { id: \"src/a.ts\", label: \"a.ts\" },\n      { id: \"src/b\", label: \"b\", children: [\n        { id: \"src/b/c.ts\", label: \"c.ts\" },\n      ]},\n    ]},\n    { id: \"README.md\", label: \"README.md\" },\n  ]}\n  selectedId={sel}\n  onSelect={setSel}\n  defaultExpandedIds={[\"src\"]}\n/>"},{"description":"Fully controlled expansion","code":"const [open, setOpen] = useState<string[]>([\"root\"]);\n\n<Tree data={tree} expandedIds={open} onExpandedChange={setOpen} />"}]},"OTPInput":{"description":"Segmented one-time-code input for verification / 2FA. CONTROLLED. onChange emits the STRING value (not an event), and onComplete fires once when every slot is filled. Paste-aware (pasting a full code fills all slots), auto-advance on input, backspace moves to the previous slot, arrow keys navigate. Drops straight into <FormField>.","import":"import { OTPInput } from \"@usevyre/react\"","props":{"value":{"type":"string","description":"Controlled value (length ≤ `length`). Omit for uncontrolled."},"defaultValue":{"type":"string","default":"\"\"","description":"Initial value when uncontrolled"},"onChange":{"type":"function","description":"(value: string) => void — emits the combined code string, NOT an event"},"onComplete":{"type":"function","description":"(value: string) => void — fired once when all slots are filled"},"length":{"type":"number","default":6,"description":"Number of slots"},"type":{"type":"enum","values":["numeric","alphanumeric"],"default":"numeric","description":"Accepted characters"},"mask":{"type":"boolean","default":false,"description":"Render dots instead of characters (like a password)"},"size":{"type":"enum","values":["sm","md","lg"],"default":"md","description":"Slot size"},"disabled":{"type":"boolean","default":false,"description":"Disable all slots"},"autoFocus":{"type":"boolean","default":false,"description":"Focus the first slot on mount"}},"antiPatterns":[{"pattern":"onChange={(e) => set(e.target.value)}","reason":"OTPInput emits the code string, not an event — there is no e.target","fix":"onChange={(value) => setCode(value)}"},{"pattern":"Six separate <Input> boxes wired by hand","reason":"Reinvents paste, auto-advance, backspace and focus management","fix":"Use <OTPInput length={6} value onChange />"},{"pattern":"Reading completion by comparing length yourself","reason":"onComplete already fires when the code is full","fix":"Use onComplete={(code) => verify(code)}"},{"pattern":"type=\"password\" to hide digits","reason":"There is no type=password; masking is a dedicated prop","fix":"Use mask (type stays numeric/alphanumeric)"}],"examples":[{"description":"2FA code with verify on complete","code":"const [code, setCode] = useState(\"\");\n\n<OTPInput\n  value={code}\n  onChange={setCode}\n  onComplete={(c) => verify(c)}\n  autoFocus\n/>"},{"description":"Inside a Form","code":"<FormField name=\"otp\" label=\"Verification code\"\n           rules={{ required: true, minLength: 6 }}>\n  <OTPInput length={6} />\n</FormField>"}]},"Carousel":{"description":"Accessible content slider for galleries, onboarding, and testimonials. CONTROLLED by a 0-based slide index. Compose CarouselSlide children (slide order = index). Snap scrolling, clickable dot indicators, prev/next arrows, ArrowLeft/Right keyboard, optional loop and autoPlay (autoplay pauses on hover/focus). onChange emits the index (not an event).","import":"import { Carousel, CarouselSlide } from \"@usevyre/react\"","subcomponents":["CarouselSlide"],"props":{"value":{"type":"number","description":"Controlled active slide (0-based). Omit for uncontrolled."},"defaultValue":{"type":"number","default":0,"description":"Initial slide when uncontrolled"},"onChange":{"type":"function","description":"(index: number) => void — emits the new active slide index"},"loop":{"type":"boolean","default":false,"description":"Wrap past the first/last slide"},"autoPlay":{"type":"boolean","default":false,"description":"Advance automatically; pauses on hover/focus"},"interval":{"type":"number","default":5000,"description":"Autoplay interval in ms"},"showArrows":{"type":"boolean","default":true,"description":"Show prev/next arrow buttons"},"showIndicators":{"type":"boolean","default":true,"description":"Show clickable dot indicators"}},"antiPatterns":[{"pattern":"onChange={(e) => set(e.target.value)}","reason":"Carousel emits the slide index number, not an event","fix":"onChange={(index) => setIndex(index)}"},{"pattern":"Putting raw elements directly in Carousel","reason":"Slides must be CarouselSlide so snap/indices/aria work","fix":"Wrap each slide in <CarouselSlide>"},{"pattern":"Building a slider with manual scroll + dot state","reason":"Reinvents snap, keyboard, autoplay-pause and a11y roles","fix":"Use <Carousel> with CarouselSlide children"},{"pattern":"autoPlay without considering reduced motion / pausing","reason":"Autoplay can be an accessibility problem if it never pauses","fix":"Carousel already pauses on hover/focus; keep interval reasonable or omit autoPlay"}],"examples":[{"description":"Image gallery with loop","code":"const [i, setI] = useState(0);\n\n<Carousel value={i} onChange={setI} loop>\n  <CarouselSlide><img src=\"/a.jpg\" alt=\"A\" /></CarouselSlide>\n  <CarouselSlide><img src=\"/b.jpg\" alt=\"B\" /></CarouselSlide>\n  <CarouselSlide><img src=\"/c.jpg\" alt=\"C\" /></CarouselSlide>\n</Carousel>"},{"description":"Onboarding, autoplay, no arrows","code":"<Carousel autoPlay interval={4000} showArrows={false}>\n  <CarouselSlide><Welcome /></CarouselSlide>\n  <CarouselSlide><Features /></CarouselSlide>\n  <CarouselSlide><GetStarted /></CarouselSlide>\n</Carousel>"}]},"CarouselSlide":{"description":"One slide inside <Carousel>. Holds arbitrary content (image, Card, testimonial). Slide order determines its index.","import":"import { Carousel, CarouselSlide } from \"@usevyre/react\"","props":{},"antiPatterns":[{"pattern":"<CarouselSlide> outside <Carousel>","reason":"Snap/measurement/aria depend on the Carousel context","fix":"Always nest CarouselSlide inside Carousel"}],"examples":[{"description":"Card slide","code":"<CarouselSlide>\n  <Card><CardBody>“Best tool ever.” — Ada</CardBody></Card>\n</CarouselSlide>"}]},"DateRangePicker":{"description":"Start/end date range picker. Built on Calendar (mode=range) with a friendlier { from, to } object API, a two-month side-by-side view, and preset shortcuts. Use this for report/filter date ranges; use DatePicker for a single date.","import":"import { DateRangePicker } from \"@usevyre/react\"","props":{"value":{"type":"{ from: Date | null; to: Date | null } | null","description":"Selected range (controlled). Pass an OBJECT, not a tuple."},"onChange":{"type":"function","description":"Callback (range: { from, to }) => void when the range changes"},"placeholder":{"type":"string","default":"Pick a date range","description":"Trigger text when no range is selected"},"numberOfMonths":{"type":"enum","values":[1,2],"default":2,"description":"How many month calendars to show side-by-side"},"presets":{"type":"boolean | DateRangePreset[]","default":false,"description":"true shows built-in presets (Today, Yesterday, Last 7/30 days, This/Last month); or pass a custom array of { label, range() }"},"minDate":{"type":"Date","description":"Earliest selectable date"},"maxDate":{"type":"Date","description":"Latest selectable date"},"disabled":{"type":"function","description":"(date: Date) => boolean — disable specific dates"},"weekStartsOn":{"type":"enum","values":[0,1],"default":1,"description":"0 = Sunday, 1 = Monday"}},"antiPatterns":[{"pattern":"value={[from, to]}","reason":"DateRangePicker uses a { from, to } object, not a [Date, Date] tuple like Calendar mode=range","fix":"Use value={{ from, to }} and read range.from / range.to"},{"pattern":"DateRangePicker for a single date","reason":"DateRangePicker always selects a start AND end","fix":"Use <DatePicker /> for a single date"},{"pattern":"presets=\"true\" (string)","reason":"presets is a boolean or an array, not a string","fix":"Use the bare prop: presets  (or presets={true})"}],"examples":[{"description":"Range picker with built-in presets","code":"const [range, setRange] = useState({ from: null, to: null });\n<DateRangePicker value={range} onChange={setRange} presets />"},{"description":"Single month, no presets","code":"<DateRangePicker value={range} onChange={setRange} numberOfMonths={1} />"}]},"Sparkline":{"description":"Tiny inline chart with no axis, legend or tooltip — for Stat cards and table cells. Takes a flat number[] (NOT data + config like the larger charts). The color is a single token string passed via the `color` prop (it has no `config` or `xKey`).","import":"import { Sparkline } from \"@usevyre/react\"","props":{"data":{"type":"number[]","description":"Series of numbers to plot (required). A flat array of numbers, not row objects."},"variant":{"type":"enum","values":["line","area","bar"],"default":"line","description":"Render style of the sparkline."},"color":{"type":"string","default":"var(--vyre-color-semantic-accent)","description":"Stroke/fill color as a token string (e.g. \"var(--vyre-color-semantic-success)\")."},"width":{"type":"number","default":80,"description":"SVG width in px."},"height":{"type":"number","default":24,"description":"SVG height in px."}},"antiPatterns":[{"pattern":"Passing row objects: data={[{ name, value }]}","reason":"Sparkline takes a flat number[], not the {name,value}[] PieChart wants or the row objects LineChart/BarChart want","fix":"data={[3, 7, 4, 9, 6]}"},{"pattern":"Expecting an axis, legend or tooltip","reason":"Sparkline is intentionally chrome-less for inline use; it has no showGrid/showLegend/showTooltip props","fix":"Use LineChart/AreaChart/BarChart for a full chart with axes and tooltip"}],"examples":[{"description":"Inline trend in a Stat card","code":"<Sparkline data={[3, 7, 4, 9, 6, 11]} />"},{"description":"Bar variant with a success token color","code":"<Sparkline data={[2, 4, 3, 8]} variant=\"bar\" color=\"var(--vyre-color-semantic-success)\" />"}]},"LineChart":{"description":"Multi-series line chart. Data + config + xKey driven (NOT Recharts-style JSX children). Each series is a key in `config` ({ label, color }); colors come ONLY from config tokens — there is no `color` prop. Grid/legend/tooltip are boolean props; the tooltip supports hover and arrow-key navigation.","import":"import { LineChart } from \"@usevyre/react\"","props":{"data":{"type":"ChartDatum[]","description":"Array of row objects (required), e.g. [{ month: \"Jan\", revenue: 10 }]."},"config":{"type":"ChartConfig","description":"Per-series settings (required): { seriesKey: { label, color } }. Colors are token strings; one line is drawn per key."},"xKey":{"type":"string","description":"Name of the field in each row used for the x-axis (required), e.g. \"month\"."},"curve":{"type":"enum","values":["linear","smooth"],"default":"linear","description":"Line interpolation."},"dots":{"type":"boolean","default":false,"description":"Draw a dot at each data point."},"width":{"type":"number","default":480,"description":"SVG width in px."},"height":{"type":"number","default":240,"description":"SVG height in px."},"showGrid":{"type":"boolean","default":true,"description":"Show background grid lines and axis labels."},"showLegend":{"type":"boolean","default":true,"description":"Show the legend; clicking a legend item toggles that series."},"showTooltip":{"type":"boolean","default":true,"description":"Show the hover/arrow-key tooltip."}},"antiPatterns":[{"pattern":"Passing series via series={...}","reason":"There is no `series` prop; LineChart derives its series from the keys of `config`","fix":"Use data (row objects) + config ({ key: { label, color } }) + xKey"},{"pattern":"Setting a single color with color=\"blue\"","reason":"There is no `color` prop; per-series color is a token inside config","fix":"config={{ revenue: { label: \"Revenue\", color: \"var(--vyre-color-semantic-accent)\" } }}"},{"pattern":"Recharts-style children like <XAxis/> or <Tooltip/>","reason":"LineChart is not composed from JSX children; grid/legend/tooltip are boolean props","fix":"Use showGrid / showLegend / showTooltip props instead of child elements"}],"examples":[{"description":"Single-series revenue line","code":"<LineChart\n  data={[{ month: \"Jan\", revenue: 10 }, { month: \"Feb\", revenue: 20 }]}\n  config={{ revenue: { label: \"Revenue\", color: \"var(--vyre-color-semantic-accent)\" } }}\n  xKey=\"month\"\n/>"},{"description":"Smooth curve with dots, no legend","code":"<LineChart data={data} config={config} xKey=\"month\" curve=\"smooth\" dots showLegend={false} />"}]},"AreaChart":{"description":"Multi-series area chart (line + filled area). Data + config + xKey driven (NOT JSX children). Series come from `config` keys; colors are config tokens (no `color` prop). Supports a fade-to-transparent gradient and stacking.","import":"import { AreaChart } from \"@usevyre/react\"","props":{"data":{"type":"ChartDatum[]","description":"Array of row objects (required), e.g. [{ month: \"Jan\", revenue: 10 }]."},"config":{"type":"ChartConfig","description":"Per-series settings (required): { seriesKey: { label, color } }. Colors are token strings."},"xKey":{"type":"string","description":"Name of the field in each row used for the x-axis (required)."},"curve":{"type":"enum","values":["linear","smooth"],"default":"linear","description":"Line/area interpolation."},"gradient":{"type":"boolean","default":true,"description":"Fill each area with a fade-to-transparent gradient (false = flat low-opacity fill)."},"stacked":{"type":"boolean","default":false,"description":"Stack series on top of each other instead of overlaying."},"width":{"type":"number","default":480,"description":"SVG width in px."},"height":{"type":"number","default":240,"description":"SVG height in px."},"showGrid":{"type":"boolean","default":true,"description":"Show background grid lines and axis labels."},"showLegend":{"type":"boolean","default":true,"description":"Show the legend; clicking a legend item toggles that series."},"showTooltip":{"type":"boolean","default":true,"description":"Show the hover/arrow-key tooltip."}},"antiPatterns":[{"pattern":"Passing series via series={...}","reason":"There is no `series` prop; AreaChart derives its series from the keys of `config`","fix":"Use data (row objects) + config ({ key: { label, color } }) + xKey"},{"pattern":"Setting a single color with color=\"blue\"","reason":"There is no `color` prop; per-series color is a token inside config","fix":"config={{ revenue: { label: \"Revenue\", color: \"var(--vyre-color-semantic-accent)\" } }}"},{"pattern":"Recharts-style children like <XAxis/> or <Tooltip/>","reason":"AreaChart is not composed from JSX children; grid/legend/tooltip are boolean props","fix":"Use showGrid / showLegend / showTooltip props instead of child elements"}],"examples":[{"description":"Single-series revenue area","code":"<AreaChart\n  data={[{ month: \"Jan\", revenue: 10 }, { month: \"Feb\", revenue: 20 }]}\n  config={{ revenue: { label: \"Revenue\", color: \"var(--vyre-color-semantic-accent)\" } }}\n  xKey=\"month\"\n/>"},{"description":"Stacked, flat fill","code":"<AreaChart data={data} config={config} xKey=\"month\" stacked gradient={false} />"}]},"BarChart":{"description":"Multi-series bar chart. Data + config + xKey driven (NOT JSX children). The x-axis is banded by data index; multiple series render as grouped side-by-side bars, or stacked when `stacked`. Colors come ONLY from config tokens (no `color` prop). Supports vertical and horizontal orientation.","import":"import { BarChart } from \"@usevyre/react\"","props":{"data":{"type":"ChartDatum[]","description":"Array of row objects (required), e.g. [{ region: \"NA\", sales: 30 }]."},"config":{"type":"ChartConfig","description":"Per-series settings (required): { seriesKey: { label, color } }. Colors are token strings; one bar group per datum."},"xKey":{"type":"string","description":"Name of the field in each row used for the category axis (required)."},"orientation":{"type":"enum","values":["vertical","horizontal"],"default":"vertical","description":"Bar direction."},"stacked":{"type":"boolean","default":false,"description":"Stack series per category instead of grouping them side-by-side."},"width":{"type":"number","default":480,"description":"SVG width in px."},"height":{"type":"number","default":240,"description":"SVG height in px."},"showGrid":{"type":"boolean","default":true,"description":"Show background grid lines and axis labels."},"showLegend":{"type":"boolean","default":true,"description":"Show the legend; clicking a legend item toggles that series."},"showTooltip":{"type":"boolean","default":true,"description":"Show the hover/arrow-key tooltip."}},"antiPatterns":[{"pattern":"Passing series via series={...}","reason":"There is no `series` prop; BarChart derives its series from the keys of `config`","fix":"Use data (row objects) + config ({ key: { label, color } }) + xKey"},{"pattern":"Setting a single color with color=\"blue\"","reason":"There is no `color` prop; per-series color is a token inside config","fix":"config={{ sales: { label: \"Sales\", color: \"var(--vyre-color-semantic-accent)\" } }}"},{"pattern":"Recharts-style children like <XAxis/> or <Tooltip/>","reason":"BarChart is not composed from JSX children; grid/legend/tooltip are boolean props","fix":"Use showGrid / showLegend / showTooltip props instead of child elements"}],"examples":[{"description":"Single-series bar chart by region","code":"<BarChart\n  data={[{ region: \"NA\", sales: 30 }, { region: \"EU\", sales: 25 }]}\n  config={{ sales: { label: \"Sales\", color: \"var(--vyre-color-semantic-accent)\" } }}\n  xKey=\"region\"\n/>"},{"description":"Horizontal, stacked two-series bars","code":"<BarChart data={data} config={config} xKey=\"region\" orientation=\"horizontal\" stacked />"}]},"PieChart":{"description":"Single-level pie/donut chart. Takes FLAT data — an array of { name, value } objects (NOT multi-series rows, and NOT a list of numbers). `config` is optional ({ name: { label, color } }); names without a config entry fall back to a built-in token color cycle. There is no `color` prop and no <Pie>/<Cell> children.","import":"import { PieChart } from \"@usevyre/react\"","props":{"data":{"type":"PieDatum[]","description":"Flat array of { name: string; value: number } objects (required), e.g. [{ name: \"Chrome\", value: 60 }]."},"config":{"type":"ChartConfig","description":"Optional per-segment settings: { name: { label, color } }. Unmatched names use a token color cycle."},"donut":{"type":"boolean","default":false,"description":"Render a hollow-center donut instead of a full pie."},"size":{"type":"number","default":240,"description":"SVG width AND height in px (the chart is square)."},"showLegend":{"type":"boolean","default":true,"description":"Show the legend; clicking a legend item toggles that segment."},"showTooltip":{"type":"boolean","default":true,"description":"Show the hover tooltip."}},"antiPatterns":[{"pattern":"Passing numbers: data={[1, 2, 3]}","reason":"PieChart needs named segments to label and color them","fix":"data={[{ name: \"Chrome\", value: 60 }, { name: \"Safari\", value: 25 }]}"},{"pattern":"Setting a single color with color=\"blue\"","reason":"There is no `color` prop; per-segment color comes from config or the built-in token cycle","fix":"Omit color (auto token cycle) or config={{ Chrome: { label: \"Chrome\", color: \"var(--vyre-color-semantic-accent)\" } }}"},{"pattern":"Recharts-style <Pie>/<Cell> children","reason":"PieChart is not composed from JSX children","fix":"Use the data prop (and donut for a ring) instead of child elements"}],"examples":[{"description":"Donut from flat name/value data (auto colors)","code":"<PieChart\n  data={[\n    { name: \"Chrome\", value: 60 },\n    { name: \"Safari\", value: 25 },\n    { name: \"Firefox\", value: 15 },\n  ]}\n  donut\n/>"},{"description":"Explicit per-segment colors via config","code":"<PieChart\n  data={[{ name: \"Chrome\", value: 60 }, { name: \"Safari\", value: 40 }]}\n  config={{ Chrome: { label: \"Chrome\", color: \"var(--vyre-color-semantic-accent)\" } }}\n/>"}]}}};
